using TestFn = void (*)();

struct TestCase {
    std::string_view name;
    std::vector<std::string_view> tags;
    std::vector<std::string_view> rule_refs;
    TestFn fn;
};

void require(bool condition, const char* message) {
    if (!condition) {
        throw std::runtime_error(message);
    }
}

[[nodiscard]] std::string replace_once(std::string text, std::string_view needle, std::string_view replacement) {
    const auto pos = text.find(needle);
    if (pos == std::string::npos) {
        throw std::runtime_error("replace_once needle not found");
    }
    text.replace(pos, needle.size(), replacement);
    return text;
}


[[nodiscard]] std::string first_line_starting_with(std::string_view text, std::string_view prefix) {
    std::size_t pos = 0;
    while (pos <= text.size()) {
        const auto end = text.find('\n', pos);
        const auto line_end = (end == std::string_view::npos) ? text.size() : end;
        const auto line = text.substr(pos, line_end - pos);
        if (line.substr(0, prefix.size()) == prefix) {
            return std::string(line);
        }
        if (end == std::string_view::npos) {
            break;
        }
        pos = end + 1U;
    }
    throw std::runtime_error("line prefix not found");
}

std::size_t first_event_index(const mtgsim::GameState& game, std::string_view kind) {
    for (std::size_t i = 0; i < game.events.size(); ++i) {
        if (game.events[i].kind == kind) {
            return i;
        }
    }
    return game.events.size();
}

[[nodiscard]] bool has_violation_code(const std::vector<mtgsim::InvariantViolation>& violations, std::string_view code) {
    return std::any_of(violations.begin(), violations.end(), [code](const mtgsim::InvariantViolation& violation) {
        return violation.code == code;
    });
}

std::string json_escape(std::string_view value) {
    std::string out;
    out.reserve(value.size() + 8U);
    for (const char ch : value) {
        switch (ch) {
            case '\\': out += "\\\\"; break;
            case '"': out += "\\\""; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default:
                if (static_cast<unsigned char>(ch) < 0x20U) {
                    out += "?";
                } else {
                    out += ch;
                }
        }
    }
    return out;
}

void write_string_array_json(const std::vector<std::string_view>& values) {
    std::cout << "[";
    for (std::size_t i = 0; i < values.size(); ++i) {
        if (i != 0U) {
            std::cout << ",";
        }
        std::cout << "\"" << json_escape(values[i]) << "\"";
    }
    std::cout << "]";
}

mtgsim::GameState make_smoke_game(std::uint64_t seed = 1234) {
    std::vector<mtgsim::CardDefinition> defs = {
        {"Sample Creature", mtgsim::TypeCreature, 2, 2},
        {"Sample Instant", mtgsim::TypeInstant, 0, 0}
    };
    std::vector<mtgsim::PlayerDeck> decks = {
        {"Alpha", std::vector<mtgsim::u32>(10, 0)},
        {"Beta", std::vector<mtgsim::u32>(10, 1)}
    };
    return mtgsim::make_game(std::move(defs), decks, seed);
}

void set_main_phase_priority(mtgsim::GameState& game, mtgsim::PlayerId active = mtgsim::PlayerId{1}) {
    game.active_player = active;
    game.priority_player = active;
    game.step = mtgsim::Step::Main1;
    game.consecutive_priority_passes = 0;
}

mtgsim::GameState make_mana_game(std::uint64_t seed = 5678) {
    mtgsim::CardDefinition forest;
    forest.name = "Sample Forest";
    forest.type_mask = mtgsim::TypeLand;
    forest.taps_for_mana = true;
    forest.tap_mana_symbol = mtgsim::ManaSymbol::Green;

    mtgsim::CardDefinition bear;
    bear.name = "Sample Bear";
    bear.type_mask = mtgsim::TypeCreature;
    bear.printed_power = 2;
    bear.printed_toughness = 2;
    bear.mana_cost.generic = 1;
    bear.mana_cost.green = 1;

    std::vector<mtgsim::CardDefinition> defs = {forest, bear};
    std::vector<mtgsim::PlayerDeck> decks = {
        {"Alpha", {0, 1}},
        {"Beta", {0, 0}}
    };
    return mtgsim::make_game(std::move(defs), decks, seed);
}

mtgsim::GameState make_committed_paid_mana_game(std::uint64_t seed = 601267) {
    auto game = make_mana_game(seed);
    mtgsim::StartOptions opts;
    opts.opening_hand_size = 0;
    opts.shuffle_libraries = false;
    mtgsim::start_game(game, opts);
    set_main_phase_priority(game);
    mtgsim::draw_card(game, mtgsim::PlayerId{1});
    const auto spell = mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Hand).back();
    const auto forest = mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Library).back();
    mtgsim::move_object(game, forest, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::tap_permanent_for_mana(game, mtgsim::PlayerId{1}, forest);
    mtgsim::add_mana(game, mtgsim::PlayerId{1}, mtgsim::ManaSymbol::Colorless);
    require(mtgsim::cast_from_hand_to_stack_paying_mana(game, mtgsim::PlayerId{1}, spell),
            "committed paid mana setup should cast the spell");
    return game;
}

mtgsim::GameState make_rollback_paid_mana_game(std::uint64_t seed = 601268) {
    auto game = make_mana_game(seed);
    mtgsim::StartOptions opts;
    opts.opening_hand_size = 0;
    opts.shuffle_libraries = false;
    mtgsim::start_game(game, opts);
    set_main_phase_priority(game);
    mtgsim::draw_card(game, mtgsim::PlayerId{1});
    const auto spell = mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Hand).back();
    mtgsim::add_mana(game, mtgsim::PlayerId{1}, mtgsim::ManaSymbol::Colorless, 2);
    require(!mtgsim::cast_from_hand_to_stack_paying_mana(game, mtgsim::PlayerId{1}, spell),
            "rollback paid mana setup should fail without colored mana");
    return game;
}

