mtgsim::GameState make_activated_game(std::uint64_t seed = 23023) {
    mtgsim::ActivatedAbilityDefinition ping;
    ping.name = "Arc ping";
    ping.mana_cost.red = 1;
    ping.tap_cost = true;
    ping.effect_kind = mtgsim::EffectKind::DealDamage;
    ping.effect_amount = 1;
    ping.target_mask = mtgsim::TargetAny;

    mtgsim::CardDefinition pinger;
    pinger.name = "Activated Pinger";
    pinger.type_mask = mtgsim::TypeCreature;
    pinger.printed_power = 1;
    pinger.printed_toughness = 1;
    pinger.activated_abilities.push_back(ping);

    mtgsim::CardDefinition target;
    target.name = "Activated Target";
    target.type_mask = mtgsim::TypeCreature;
    target.printed_power = 2;
    target.printed_toughness = 2;

    mtgsim::ActivatedAbilityDefinition grow;
    grow.name = "Growth burst";
    grow.effect_kind = mtgsim::EffectKind::AddCounters;
    grow.effect_amount = 1;
    grow.effect_counter_kind = mtgsim::CounterKind::PlusOnePlusOne;
    grow.target_mask = mtgsim::TargetObject;

    mtgsim::ActivatedAbilityDefinition heal;
    heal.name = "Share vitality";
    heal.effect_kind = mtgsim::EffectKind::GainLife;
    heal.effect_amount = 2;
    heal.target_mask = mtgsim::TargetPlayer;

    mtgsim::ActivatedAbilityDefinition make_token;
    make_token.name = "Make servo";
    make_token.effect_kind = mtgsim::EffectKind::CreateToken;
    make_token.effect_amount = 1;
    make_token.created_token_definition_index = 3;
    make_token.sorcery_speed = true;

    mtgsim::CardDefinition engine;
    engine.name = "Activated Engine";
    engine.type_mask = mtgsim::TypeArtifact;
    engine.activated_abilities.push_back(grow);
    engine.activated_abilities.push_back(heal);
    engine.activated_abilities.push_back(make_token);

    mtgsim::CardDefinition servo;
    servo.name = "Activated Servo Token";
    servo.type_mask = mtgsim::TypeArtifact | mtgsim::TypeCreature;
    servo.printed_power = 1;
    servo.printed_toughness = 1;

    std::vector<mtgsim::CardDefinition> defs = {pinger, target, engine, servo};
    std::vector<mtgsim::PlayerDeck> decks = {
        {"Alpha", {0, 2}},
        {"Beta", {1}}
    };
    return mtgsim::make_game(std::move(defs), decks, seed);
}

