void start_empty_unshuffled(mtgsim::GameState& game) {
    mtgsim::StartOptions opts;
    opts.opening_hand_size = 0;
    opts.shuffle_libraries = false;
    mtgsim::start_game(game, opts);
    set_main_phase_priority(game);
}

void make_ready(mtgsim::GameState& game, mtgsim::ObjectId object_id) {
    auto& obj = mtgsim::object(game, object_id);
    const auto& controller = mtgsim::player(game, obj.controller);
    obj.controlled_since_turn_start_index = controller.turn_start_index == 0U ? 0U : controller.turn_start_index - 1U;
}

mtgsim::u32 count_actions(const mtgsim::GameState& game, mtgsim::PlayerId player_id, mtgsim::ActionKind kind) {
    const auto actions = mtgsim::enumerate_legal_actions(game, player_id);
    return static_cast<mtgsim::u32>(std::count_if(actions.begin(), actions.end(), [kind](const mtgsim::LegalAction& action) {
        return action.kind == kind;
    }));
}

void test_start_game_draws_opening_hands() {
    auto game = make_smoke_game();
    mtgsim::start_game(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Hand).size() == 7, "p1 should draw opening hand");
    require(mtgsim::zone(game, mtgsim::PlayerId{2}, mtgsim::Zone::Hand).size() == 7, "p2 should draw opening hand");
    require(mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Library).size() == 3, "p1 library should shrink");
    require(mtgsim::zone(game, mtgsim::PlayerId{2}, mtgsim::Zone::Library).size() == 3, "p2 library should shrink");
    require(mtgsim::alive_player_count(game) == 2, "both players should be alive");
}

void test_minimal_stack_resolution_for_permanent() {
    auto game = make_smoke_game();
    mtgsim::start_game(game);
    const auto object_id = mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Hand).back();
    mtgsim::cast_from_hand_to_stack(game, mtgsim::PlayerId{1}, object_id);
    mtgsim::assert_valid_game_state(game);
    require(game.stack.size() == 1, "spell should be on stack");
    mtgsim::pass_priority(game);
    mtgsim::pass_priority(game);
    mtgsim::assert_valid_game_state(game);
    require(game.stack.empty(), "stack should be empty after all players pass");
    require(mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield).size() == 1, "permanent should resolve to battlefield");
}

void test_minimal_stack_resolution_for_nonpermanent() {
    auto game = make_smoke_game();
    mtgsim::start_game(game);
    const auto object_id = mtgsim::zone(game, mtgsim::PlayerId{2}, mtgsim::Zone::Hand).back();
    mtgsim::cast_from_hand_to_stack(game, mtgsim::PlayerId{2}, object_id);
    mtgsim::pass_priority(game);
    mtgsim::pass_priority(game);
    mtgsim::assert_valid_game_state(game);
    require(game.stack.empty(), "stack should be empty after instant resolves");
    require(mtgsim::zone(game, mtgsim::PlayerId{2}, mtgsim::Zone::Graveyard).size() == 1, "nonpermanent should resolve to graveyard");
}

void test_state_based_life_loss() {
    auto game = make_smoke_game();
    mtgsim::start_game(game);
    mtgsim::lose_life(game, mtgsim::PlayerId{2}, 20);
    mtgsim::apply_state_based_actions(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::player(game, mtgsim::PlayerId{2}).lost, "player at non-positive life should lose");
}

