void test_sacrifice_cost_cast_queues_trigger_above_spell() {
    mtgsim::CardDefinition celebrant;
    celebrant.name = "Cost Celebrant";
    celebrant.type_mask = mtgsim::TypeCreature;
    celebrant.printed_power = 1;
    celebrant.printed_toughness = 1;
    celebrant.trigger.event = mtgsim::TriggerEventKind::CreatureDies;
    celebrant.trigger.effect_kind = mtgsim::EffectKind::GainLife;
    celebrant.trigger.effect_amount = 2;
    celebrant.trigger.exclude_source = false;

    mtgsim::CardDefinition ritual;
    ritual.name = "Costly Ritual";
    ritual.type_mask = mtgsim::TypeSorcery;
    ritual.effect_kind = mtgsim::EffectKind::GainLife;
    ritual.effect_amount = 1;
    ritual.sacrifice_cost.count = 1;
    ritual.sacrifice_cost.required_type_mask = mtgsim::TypeCreature;

    std::vector<mtgsim::CardDefinition> defs = {celebrant, ritual};
    std::vector<mtgsim::PlayerDeck> decks = {{"Alpha", {0, 1}}, {"Beta", {0}}};
    auto game = mtgsim::make_game(std::move(defs), decks, 601203);
    set_main_phase_priority(game);
    const mtgsim::ObjectId celebrant_id{1};
    const mtgsim::ObjectId ritual_id{2};
    mtgsim::move_object(game, celebrant_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, ritual_id, mtgsim::PlayerId{1}, mtgsim::Zone::Hand);

    require(mtgsim::cast_from_hand_to_stack_paying_mana(game, mtgsim::PlayerId{1}, ritual_id), "spell with a sacrifice cost should be castable when a matching permanent exists");
    require(mtgsim::object(game, celebrant_id).zone == mtgsim::Zone::Graveyard, "sacrifice cost should move the selected creature to graveyard before resolution");
    require(game.stack.size() == 1U && game.stack.back() == ritual_id, "costly spell should remain on stack after its sacrifice cost is paid");
    require(mtgsim::pending_trigger_count(game) == 1U, "dies trigger from sacrifice cost should be pending while the spell is on stack");
    const auto cast_event = first_event_index(game, "cast_spell");
    const auto cost_event = first_event_index(game, "pay_sacrifice_cost");
    require(cast_event < game.events.size(), "casting event should be recorded");
    require(cost_event < game.events.size(), "sacrifice-cost payment event should be recorded");
    require(cast_event < cost_event, "spell should move to stack before sacrifice costs are paid");

    const auto gated_actions = mtgsim::enumerate_legal_actions(game, game.priority_player);
    require(gated_actions.size() == 1U, "pending triggers should gate priority even while a spell remains on stack");
    require(gated_actions.front().kind == mtgsim::ActionKind::PutPendingTriggersOnStack, "only put-pending-triggers action should be available before priority can pass");
    require(mtgsim::apply_action(game, gated_actions.front()), "put-pending-triggers action should succeed");
    require(game.stack.size() == 2U, "triggered ability should be placed above the original spell");
    require(mtgsim::object(game, game.stack.back()).ability_object, "top stack object should be the cost-triggered ability");

    mtgsim::pass_priority(game);
    mtgsim::pass_priority(game);
    require(mtgsim::player(game, mtgsim::PlayerId{1}).life == 22, "cost-triggered ability should resolve before the spell underneath it");
    require(game.stack.size() == 1U && game.stack.back() == ritual_id, "original spell should still be waiting after the trigger resolves");

    mtgsim::pass_priority(game);
    mtgsim::pass_priority(game);
    require(mtgsim::player(game, mtgsim::PlayerId{1}).life == 23, "original spell should resolve after the trigger above it");
    require(game.stack.empty(), "stack should be empty after resolving trigger and spell");
    mtgsim::assert_valid_game_state(game);
}

