void test_targeted_spell_locks_target_before_sacrifice_costs_are_paid() {
    mtgsim::CardDefinition morsel;
    morsel.name = "Morsel Bear";
    morsel.type_mask = mtgsim::TypeCreature;
    morsel.printed_power = 1;
    morsel.printed_toughness = 1;

    mtgsim::CardDefinition growth;
    growth.name = "Devouring Growth";
    growth.type_mask = mtgsim::TypeSorcery;
    growth.effect_kind = mtgsim::EffectKind::AddCounters;
    growth.effect_amount = 1;
    growth.effect_counter_kind = mtgsim::CounterKind::PlusOnePlusOne;
    growth.target_mask = mtgsim::TargetObject;
    growth.sacrifice_cost.count = 1;
    growth.sacrifice_cost.required_type_mask = mtgsim::TypeCreature;

    std::vector<mtgsim::CardDefinition> defs = {morsel, growth};
    std::vector<mtgsim::PlayerDeck> decks = {{"Alpha", {0, 1}}, {"Beta", {0}}};
    auto game = mtgsim::make_game(std::move(defs), decks, 601205);
    set_main_phase_priority(game);
    const mtgsim::ObjectId morsel_id{1};
    const mtgsim::ObjectId growth_id{2};
    mtgsim::move_object(game, morsel_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, growth_id, mtgsim::PlayerId{1}, mtgsim::Zone::Hand);

    require(mtgsim::cast_from_hand_to_stack_paying_mana_with_target(game, mtgsim::PlayerId{1}, growth_id, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = morsel_id}), "targeted spell with sacrifice cost should be castable");
    require(game.stack.size() == 1U && game.stack.back() == growth_id, "spell should be on stack after all costs are paid");
    require(mtgsim::object(game, growth_id).targets.size() == 1U, "target should be stored on stack spell before costs are paid");
    require(mtgsim::object(game, morsel_id).zone == mtgsim::Zone::Graveyard, "sacrifice cost should be able to sacrifice the chosen target after target choice");
    require(!mtgsim::target_ref_is_legal_for_source_object(game, mtgsim::object(game, growth_id).targets.front(), mtgsim::TargetObject, growth_id), "chosen target should be stale after it is sacrificed as a cost");
    const auto cast_event = first_event_index(game, "cast_spell");
    const auto choose_event = first_event_index(game, "choose_target");
    const auto cost_event = first_event_index(game, "pay_sacrifice_cost");
    require(cast_event < choose_event && choose_event < cost_event, "target choice should be recorded before sacrifice costs are paid");

    mtgsim::resolve_top_of_stack(game);
    require(mtgsim::object(game, growth_id).zone == mtgsim::Zone::Graveyard, "spell with only a stale target should still leave stack on resolution");
    require(mtgsim::object_counter_count(game, morsel_id, mtgsim::CounterKind::PlusOnePlusOne) == 0U, "stale sacrificed target should not receive counters from the resolving spell");
    mtgsim::assert_valid_game_state(game);
}

void test_sacrifice_cost_orders_attached_permanents_before_enchanted_sources() {
    mtgsim::CardDefinition bear;
    bear.name = "Anchor Bear";
    bear.type_mask = mtgsim::TypeCreature;
    bear.printed_power = 2;
    bear.printed_toughness = 2;

    mtgsim::CardDefinition aura;
    aura.name = "Tether Aura";
    aura.type_mask = mtgsim::TypeEnchantment;
    aura.attachment_kind = mtgsim::AttachmentKind::Aura;
    aura.target_mask = mtgsim::TargetObject;

    mtgsim::CardDefinition rite;
    rite.name = "Severing Rite";
    rite.type_mask = mtgsim::TypeSorcery;
    rite.effect_kind = mtgsim::EffectKind::GainLife;
    rite.effect_amount = 1;
    rite.sacrifice_cost.count = 2;
    rite.sacrifice_cost.required_type_mask = mtgsim::TypeCreature | mtgsim::TypeEnchantment;

    std::vector<mtgsim::CardDefinition> defs = {bear, aura, rite};
    std::vector<mtgsim::PlayerDeck> decks = {{"Alpha", {0, 1, 2}}, {"Beta", {0}}};
    auto game = mtgsim::make_game(std::move(defs), decks, 601206);
    set_main_phase_priority(game);
    const mtgsim::ObjectId bear_id{1};
    const mtgsim::ObjectId aura_id{2};
    const mtgsim::ObjectId rite_id{3};
    mtgsim::move_object(game, bear_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, aura_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, rite_id, mtgsim::PlayerId{1}, mtgsim::Zone::Hand);
    require(mtgsim::attach_object_to(game, aura_id, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = bear_id}), "fixture aura should attach to the sacrifice target creature");

    const auto zone_changes_before = mtgsim::zone_change_record_count(game);
    require(mtgsim::cast_from_hand_to_stack_paying_mana(game, mtgsim::PlayerId{1}, rite_id), "sacrifice-cost payment should order an attached Aura before the enchanted permanent instead of rejecting a legal set");
    require(game.stack.size() == 1U && game.stack.back() == rite_id, "spell should be on stack after the ordered sacrifice payment succeeds");
    require(mtgsim::object(game, aura_id).zone == mtgsim::Zone::Graveyard, "Aura should be sacrificed explicitly, not swept to graveyard by losing its enchanted object");
    require(mtgsim::object(game, bear_id).zone == mtgsim::Zone::Graveyard, "enchanted creature should be sacrificed after the attached Aura");
    require(mtgsim::zone_change_record_count(game) == zone_changes_before + 3U, "cast plus two explicit sacrifices should create exactly three zone-change records");
    const auto cost_event = first_event_index(game, "pay_sacrifice_cost");
    require(cost_event < game.events.size(), "ordered sacrifice payment should be logged");
    const auto aura_pos = game.events[cost_event].detail.find("Tether Aura");
    const auto bear_pos = game.events[cost_event].detail.find("Anchor Bear");
    require(aura_pos != std::string::npos && bear_pos != std::string::npos && aura_pos < bear_pos, "sacrifice detail should expose attachment-safe payment order");
    mtgsim::assert_valid_game_state(game);
}


void test_activated_sacrifice_cost_can_sacrifice_source_and_queue_trigger_above_ability() {
    mtgsim::CardDefinition celebrant;
    celebrant.name = "Blood Celebrant";
    celebrant.type_mask = mtgsim::TypeArtifact | mtgsim::TypeCreature;
    celebrant.printed_power = 1;
    celebrant.printed_toughness = 1;
    celebrant.trigger.event = mtgsim::TriggerEventKind::CreatureDies;
    celebrant.trigger.effect_kind = mtgsim::EffectKind::GainLife;
    celebrant.trigger.effect_amount = 2;
    celebrant.trigger.exclude_source = false;
    mtgsim::ActivatedAbilityDefinition ability;
    ability.name = "blood rite";
    ability.effect_kind = mtgsim::EffectKind::GainLife;
    ability.effect_amount = 1;
    ability.sacrifice_cost.count = 1;
    ability.sacrifice_cost.required_type_mask = mtgsim::TypeCreature;
    celebrant.activated_abilities.push_back(ability);

    std::vector<mtgsim::CardDefinition> defs = {celebrant};
    std::vector<mtgsim::PlayerDeck> decks = {{"Alpha", {0}}, {"Beta", {0}}};
    auto game = mtgsim::make_game(std::move(defs), decks, 602240);
    set_main_phase_priority(game);
    const mtgsim::ObjectId celebrant_id{1};
    mtgsim::move_object(game, celebrant_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);

    require(mtgsim::can_activate_activated_ability(game, mtgsim::PlayerId{1}, celebrant_id, 1U), "self-sacrifice activated ability should be payable while its source is on the battlefield");
    require(mtgsim::activate_activated_ability(game, mtgsim::PlayerId{1}, celebrant_id, 1U), "activation should create a stack object before sacrificing the source");
    require(mtgsim::object(game, celebrant_id).zone == mtgsim::Zone::Graveyard, "activated sacrifice cost should be allowed to sacrifice the source permanent");
    require(game.stack.size() == 1U, "activated ability should remain on the stack after its source is sacrificed");
    require(mtgsim::object(game, game.stack.back()).ability_object, "stack entry should be a synthetic activated ability object");
    require(mtgsim::pending_trigger_count(game) == 1U, "self-sacrifice cost should queue the source's dies trigger from LKI");

    const auto gated_actions = mtgsim::enumerate_legal_actions(game, game.priority_player);
    require(gated_actions.size() == 1U, "pending triggers should gate priority above an activated ability too");
    require(gated_actions.front().kind == mtgsim::ActionKind::PutPendingTriggersOnStack, "trigger gate should expose only put-pending-triggers");
    require(mtgsim::apply_action(game, gated_actions.front()), "put-pending-triggers should place the dies trigger above the activated ability");
    require(game.stack.size() == 2U, "dies trigger should be stacked above the self-sacrificing activated ability");

    mtgsim::pass_priority(game);
    mtgsim::pass_priority(game);
    require(mtgsim::player(game, mtgsim::PlayerId{1}).life == 22, "dies trigger should resolve before the activated ability underneath it");
    require(game.stack.size() == 1U, "activated ability should still wait after the trigger resolves");

    mtgsim::pass_priority(game);
    mtgsim::pass_priority(game);
    require(mtgsim::player(game, mtgsim::PlayerId{1}).life == 23, "activated ability should resolve after its source has been sacrificed");
    require(game.stack.empty(), "stack should be empty after resolving trigger and ability");
    mtgsim::assert_valid_game_state(game);
}

void test_activated_ability_locks_target_before_activation_costs_are_paid() {
    mtgsim::CardDefinition zealot;
    zealot.name = "Doomed Zealot";
    zealot.type_mask = mtgsim::TypeCreature;
    zealot.printed_power = 1;
    zealot.printed_toughness = 1;
    mtgsim::ActivatedAbilityDefinition ability;
    ability.name = "last spark";
    ability.effect_kind = mtgsim::EffectKind::DealDamage;
    ability.effect_amount = 1;
    ability.target_mask = mtgsim::TargetAny;
    ability.sacrifice_cost.count = 1;
    ability.sacrifice_cost.required_type_mask = mtgsim::TypeCreature;
    zealot.activated_abilities.push_back(ability);

    std::vector<mtgsim::CardDefinition> defs = {zealot};
    std::vector<mtgsim::PlayerDeck> decks = {{"Alpha", {0}}, {"Beta", {0}}};
    auto game = mtgsim::make_game(std::move(defs), decks, 602242);
    set_main_phase_priority(game);
    const mtgsim::ObjectId zealot_id{1};
    mtgsim::move_object(game, zealot_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);

    const mtgsim::TargetRef self_target{.kind = mtgsim::TargetKind::Object, .object = zealot_id};
    require(mtgsim::can_activate_activated_ability(game, mtgsim::PlayerId{1}, zealot_id, 1U, self_target), "activated ability should choose its target before sacrificing the source");
    require(mtgsim::activate_activated_ability(game, mtgsim::PlayerId{1}, zealot_id, 1U, self_target), "activation with a self-target and self-sacrifice cost should succeed");
    const auto stack_event = first_event_index(game, "activated_ability_put_on_stack");
    const auto choose_event = first_event_index(game, "choose_target");
    const auto cost_event = first_event_index(game, "pay_sacrifice_cost");
    require(stack_event < choose_event, "activated ability stack object should exist before target choice is recorded");
    require(choose_event < cost_event, "target choice should be locked before activation sacrifice costs are paid");
    require(mtgsim::object(game, zealot_id).zone == mtgsim::Zone::Graveyard, "activation sacrifice cost should move the targeted source to graveyard");
    require(game.stack.size() == 1U, "activated ability should remain on the stack after paying its source sacrifice cost");

    mtgsim::pass_priority(game);
    mtgsim::pass_priority(game);
    require(mtgsim::object(game, zealot_id).damage_marked == 0U, "source target that left the battlefield should be illegal at resolution");
    require(game.stack.empty(), "stale-target activated ability should resolve away without effect");
    mtgsim::assert_valid_game_state(game);
}

