void test_activated_ability_tap_cost_locks_source_before_auto_mana_payment() {
    mtgsim::CardDefinition lens;
    lens.name = "Self Funding Lens";
    lens.type_mask = mtgsim::TypeArtifact;
    lens.taps_for_mana = true;
    lens.tap_mana_symbol = mtgsim::ManaSymbol::Colorless;
    mtgsim::ActivatedAbilityDefinition pulse;
    pulse.name = "focus pulse";
    pulse.effect_kind = mtgsim::EffectKind::GainLife;
    pulse.effect_amount = 1;
    pulse.tap_cost = true;
    pulse.mana_cost.generic = 1;
    lens.activated_abilities.push_back(pulse);

    mtgsim::CardDefinition battery;
    battery.name = "External Battery";
    battery.type_mask = mtgsim::TypeArtifact;
    battery.taps_for_mana = true;
    battery.tap_mana_symbol = mtgsim::ManaSymbol::Colorless;

    std::vector<mtgsim::CardDefinition> defs = {lens, battery};
    std::vector<mtgsim::PlayerDeck> decks = {{"Alpha", {0, 1}}, {"Beta", {1}}};
    auto game = mtgsim::make_game(std::move(defs), decks, 602243);
    set_main_phase_priority(game);
    const mtgsim::ObjectId lens_id{1};
    const mtgsim::ObjectId battery_id{2};
    mtgsim::move_object(game, lens_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);

    const auto failed_object_count_before = game.objects.size();
    const auto failed_stack_placements_before = mtgsim::stack_placement_record_count(game);
    require(!mtgsim::can_activate_activated_ability(game, mtgsim::PlayerId{1}, lens_id, 1U), "tap-cost activation should not fund its mana cost by tapping the same source first");
    require(!mtgsim::activate_activated_ability(game, mtgsim::PlayerId{1}, lens_id, 1U), "direct activation should reject the self double-tap payment path instead of throwing or staging a partial ability");
    require(game.objects.size() == failed_object_count_before, "failed double-tap activation should not leak a synthetic stack object");
    require(game.stack.empty(), "failed double-tap activation should leave the stack empty");
    require(mtgsim::stack_placement_record_count(game) == failed_stack_placements_before, "failed double-tap activation should not leak a stack placement record");
    require(!mtgsim::object(game, lens_id).tapped, "failed double-tap activation should leave the source untapped");
    require(mtgsim::player(game, mtgsim::PlayerId{1}).mana_pool.empty(), "failed double-tap activation should not leave produced mana behind");

    mtgsim::move_object(game, battery_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    require(mtgsim::can_activate_activated_ability(game, mtgsim::PlayerId{1}, lens_id, 1U), "tap-cost activation should become payable from an external mana source");
    require(mtgsim::activate_activated_ability(game, mtgsim::PlayerId{1}, lens_id, 1U), "activation should pay mana from the external source and tap its own source only for the tap cost");
    require(mtgsim::object(game, battery_id).tapped, "external source should be tapped for the mana cost");
    require(mtgsim::object(game, lens_id).tapped, "ability source should be tapped for the tap cost");
    require(mtgsim::player(game, mtgsim::PlayerId{1}).mana_pool.empty(), "successful activation should spend the produced mana");
    const auto* activation_payment = mtgsim::latest_mana_change_record(game);
    require(activation_payment != nullptr && activation_payment->kind == mtgsim::ManaChangeKind::Paid, "successful activation should finish with a paid mana-change record");
    require(activation_payment->auto_payment, "tap-cost activation payment should be marked as automatic payment");
    require(activation_payment->auto_payment_mana_ability_count == 1U, "tap-cost activation should record the external mana-ability plan step");
    require(activation_payment->auto_payment_locked_tap_source_count == 1U, "tap-cost activation should record the locked source tap set");
    require(activation_payment->auto_payment_plan_hash != 0U, "tap-cost activation should record a stable auto-payment plan hash");
    require(game.stack.size() == 1U && mtgsim::object(game, game.stack.back()).ability_object, "successful activation should place one synthetic ability on the stack");
    mtgsim::assert_valid_game_state(game);
}

void test_validator_rejects_payment_plan_locked_tap_source_reused_as_step() {
    mtgsim::CardDefinition lens;
    lens.name = "Locked Lens";
    lens.type_mask = mtgsim::TypeArtifact;
    lens.taps_for_mana = true;
    lens.tap_mana_symbol = mtgsim::ManaSymbol::Colorless;
    mtgsim::ActivatedAbilityDefinition pulse;
    pulse.name = "focus pulse";
    pulse.effect_kind = mtgsim::EffectKind::GainLife;
    pulse.effect_amount = 1;
    pulse.tap_cost = true;
    pulse.mana_cost.generic = 1;
    lens.activated_abilities.push_back(pulse);

    mtgsim::CardDefinition battery;
    battery.name = "External Battery";
    battery.type_mask = mtgsim::TypeArtifact;
    battery.taps_for_mana = true;
    battery.tap_mana_symbol = mtgsim::ManaSymbol::Colorless;

    std::vector<mtgsim::CardDefinition> defs = {lens, battery};
    std::vector<mtgsim::PlayerDeck> decks = {{"Alpha", {0, 1}}, {"Beta", {1}}};
    auto game = mtgsim::make_game(std::move(defs), decks, 602244);
    set_main_phase_priority(game);
    const mtgsim::ObjectId lens_id{1};
    const mtgsim::ObjectId battery_id{2};
    mtgsim::move_object(game, lens_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, battery_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);

    require(mtgsim::activate_activated_ability(game, mtgsim::PlayerId{1}, lens_id, 1U), "setup should produce a locked activation payment plan paid by an external tap source");
    const auto* plan = mtgsim::latest_mana_payment_plan_record(game);
    require(plan != nullptr, "setup should leave a typed payment-plan record");
    require(plan->locked_tap_sources.size() == 1U, "setup should lock the activation source before auto-mana planning");
    require(plan->mana_ability_steps.size() == 1U && plan->mana_ability_steps.front().tap_cost, "setup should execute one external tap-cost mana step");
    require(plan->locked_tap_sources.front().source == lens_id, "setup should lock the activated ability source, not the external payer");
    require(plan->mana_ability_steps.front().source == battery_id, "setup should pay with the external battery step");
    mtgsim::assert_valid_game_state(game);

    auto corrupted = game;
    auto& corrupted_plan = corrupted.mana_payment_plan_records.back();
    corrupted_plan.locked_tap_sources.front().source = corrupted_plan.mana_ability_steps.front().source;
    corrupted_plan.locked_tap_sources.front().source_zone_change_index = corrupted_plan.mana_ability_steps.front().source_zone_change_index;
    const auto repaired_hash = mtgsim::mana_payment_plan_record_identity_hash(corrupted_plan);
    corrupted_plan.plan_hash = repaired_hash;
    require(corrupted_plan.paid_mana_change_record_index != 0U, "setup should link the plan to the final paid mana record");
    corrupted.mana_change_records[corrupted_plan.paid_mana_change_record_index - 1U].auto_payment_plan_hash = repaired_hash;

    const auto violations = mtgsim::validate_game_state(corrupted);
    require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& violation) {
        return violation.code == "mana_payment_plan_record.locked_source_used_as_tap_step";
    }), "validator should reject a payment plan that both locks a tap source and reuses it as a tap-cost mana step");
}

