    const auto bolt = mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Hand).back();
    const auto target_bear = mtgsim::zone(game, mtgsim::PlayerId{2}, mtgsim::Zone::Library).back();
    mtgsim::move_object(game, target_bear, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    mtgsim::add_mana(game, mtgsim::PlayerId{1}, mtgsim::ManaSymbol::Red);
    require(mtgsim::cast_from_hand_to_stack_paying_mana_with_target(game, mtgsim::PlayerId{1}, bolt, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = target_bear}), "bolt should target battlefield object");
    mtgsim::pass_priority(game);
