    const auto page0 = mtgsim::enumerate_legal_action_page(game, mtgsim::PlayerId{2}, 0U, 128U);
    require(page0.schema_version == mtgsim::kLegalActionPageSchemaVersion, "block page should carry the current legal-action page schema version");
    require(page0.kind == mtgsim::ChoiceRequestKind::DeclareBlockers, "block page should carry the declaration choice kind");
    require(page0.actions.size() == 128U && !page0.complete && page0.next_cursor == 128U, "first block page should expose a resumable prefix");
    require(page0.total_actions_lower_bound == 129U && !page0.total_actions_exact && page0.remaining_actions_lower_bound == 1U,
            "first block page should expose count lower-bound continuation evidence");

    const auto page1 = mtgsim::enumerate_legal_action_page(game, mtgsim::PlayerId{2}, page0.next_cursor, 128U);
    require(page1.actions.size() == 128U, "second block page should expose the other half of the 8-blocker domain");
    require(page1.complete && page1.next_cursor == 256U && page1.actions_seen == 256U, "second block page should terminate at the exact block domain size");
    require(page1.total_actions_exact && page1.total_actions_lower_bound == 256U && page1.remaining_actions_lower_bound == 0U,
            "second block page should expose exact total count evidence");

    std::vector<mtgsim::BlockAssignment> all_blockers;
