void test_simultaneous_sba_dies_triggers_share_pre_batch_lki_snapshot() {
    mtgsim::CardDefinition left;
    left.name = "Left Last-Looker";
    left.type_mask = mtgsim::TypeCreature;
    left.printed_power = 1;
    left.printed_toughness = 1;
    left.trigger.event = mtgsim::TriggerEventKind::CreatureDies;
    left.trigger.effect_kind = mtgsim::EffectKind::GainLife;
    left.trigger.effect_amount = 1;
    left.trigger.exclude_source = false;

    mtgsim::CardDefinition right = left;
    right.name = "Right Last-Looker";

    std::vector<mtgsim::CardDefinition> defs = {left, right};
    std::vector<mtgsim::PlayerDeck> decks = {
        {"Alpha", {0, 1}},
        {"Beta", {}}
    };
    auto game = mtgsim::make_game(std::move(defs), decks, 70460310);
    start_empty_unshuffled(game);

    const auto left_id = mtgsim::ObjectId{1};
    const auto right_id = mtgsim::ObjectId{2};
    mtgsim::move_object(game, left_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, right_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    const auto left_battlefield_zc = mtgsim::object(game, left_id).zone_change_index;
    const auto right_battlefield_zc = mtgsim::object(game, right_id).zone_change_index;

    mtgsim::mark_damage(game, left_id, 1U);
    mtgsim::mark_damage(game, right_id, 1U);
    mtgsim::apply_state_based_actions(game);

    require(mtgsim::object(game, left_id).zone == mtgsim::Zone::Graveyard, "left creature should die in the same SBA check");
    require(mtgsim::object(game, right_id).zone == mtgsim::Zone::Graveyard, "right creature should die in the same SBA check");
    require(mtgsim::pending_trigger_count(game) == 4U, "two simultaneous self/other dies triggers should see both death events from the pre-SBA LKI snapshot");

    const auto saw_left_source_for_right_death = std::any_of(game.trigger_records.begin(), game.trigger_records.end(), [&](const mtgsim::TriggerRecord& record) {
        return record.event == mtgsim::TriggerEventKind::CreatureDies &&
               record.subject == right_id &&
               record.source == left_id &&
               record.source_zone_change_index == left_battlefield_zc;
    });
    const auto saw_right_source_for_left_death = std::any_of(game.trigger_records.begin(), game.trigger_records.end(), [&](const mtgsim::TriggerRecord& record) {
        return record.event == mtgsim::TriggerEventKind::CreatureDies &&
               record.subject == left_id &&
               record.source == right_id &&
               record.source_zone_change_index == right_battlefield_zc;
    });
    require(saw_left_source_for_right_death, "left source LKI should still observe right's simultaneous death after left already moved");
    require(saw_right_source_for_left_death, "right source LKI should observe left's simultaneous death");
    mtgsim::assert_valid_game_state(game);
}

void test_targeted_trigger_chooses_legal_target_when_put_on_stack() {
    mtgsim::CardDefinition spark;
    spark.name = "Spark Watcher";
    spark.type_mask = mtgsim::TypeCreature;
    spark.printed_power = 1;
    spark.printed_toughness = 1;
    spark.color_mask = mtgsim::ColorRed;
    spark.trigger.event = mtgsim::TriggerEventKind::CreatureEntersBattlefield;
    spark.trigger.effect_kind = mtgsim::EffectKind::DealDamage;
    spark.trigger.effect_amount = 1;
    spark.trigger.target_mask = mtgsim::TargetPlayer;
    spark.trigger.exclude_source = true;

    mtgsim::CardDefinition bear;
    bear.name = "Trigger Bear";
    bear.type_mask = mtgsim::TypeCreature;
    bear.printed_power = 2;
    bear.printed_toughness = 2;

    std::vector<mtgsim::CardDefinition> defs = {spark, bear};
    std::vector<mtgsim::PlayerDeck> decks = {
        {"Alpha", {1}},
        {"Beta", {0}}
    };
    auto game = mtgsim::make_game(std::move(defs), decks, 60335);
    start_empty_unshuffled(game);

    const auto bear_id = mtgsim::ObjectId{1};
    const auto watcher_id = mtgsim::ObjectId{2};
    mtgsim::move_object(game, watcher_id, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    require(mtgsim::pending_trigger_count(game) == 0U, "watcher should not trigger on itself with exclude_source");
    mtgsim::move_object(game, bear_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    require(mtgsim::pending_trigger_count(game) == 1U, "targeted trigger should be pending after another creature enters");

    mtgsim::put_pending_triggers_on_stack(game);
    require(game.stack.size() == 1U, "targeted triggered ability should be on the stack");
    const auto ability_id = game.stack.back();
    const auto& ability = mtgsim::object(game, ability_id);
    require(ability.targets.size() == 1U, "triggered ability should receive a deterministic target choice");
    require(ability.targets.front() == mtgsim::TargetRef{.kind = mtgsim::TargetKind::Player, .player = mtgsim::PlayerId{1}}, "targeted trigger should choose the first legal player target deterministically");
    require(mtgsim::object_color_mask(game, ability_id) == mtgsim::ColorRed, "triggered ability should carry source color snapshot for protection/damage legality");
    require(game.trigger_records.size() == 1U, "targeted trigger should have one structured audit row");
    const auto& trigger_record = game.trigger_records.front();
    require(trigger_record.target_choice_recorded, "stacked targeted trigger should record the 603.3d choice gate");
    require(!trigger_record.no_legal_choices, "stacked targeted trigger should not claim no legal choices");
    require(trigger_record.required_target_count == 1U, "stacked targeted trigger should record one required target");
    require(trigger_record.legal_target_set_count >= 1U, "stacked targeted trigger should record legal target set cardinality");
    require(trigger_record.chosen_targets == ability.targets, "TriggerRecord chosen_targets should match the synthetic stack object targets exactly");
    require(trigger_record.choice_target_set_hash == mtgsim::target_choice_set_hash(trigger_record.chosen_targets),
            "TriggerRecord target-choice hash should seal the chosen target vector");

    mtgsim::pass_priority(game);
    mtgsim::pass_priority(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::player(game, mtgsim::PlayerId{1}).life == 19, "targeted trigger should resolve damage to the chosen player");
    require(mtgsim::player(game, mtgsim::PlayerId{2}).life == 20, "targeted trigger should not damage its controller in this deterministic fixture");
}

