    shielded.name = "Shielded Bear";
    shielded.type_mask = mtgsim::TypeCreature;
    shielded.printed_power = 2;
    shielded.printed_toughness = 2;
    shielded.protection_color_mask = mtgsim::ColorRed;

    mtgsim::CardDefinition plain;
    plain.name = "Plain Bear";
