    const auto shielded_id = mtgsim::ObjectId{1};
    const auto plain_id = mtgsim::ObjectId{2};
    const auto martyr_id = mtgsim::ObjectId{3};
    mtgsim::move_object(game, shielded_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, plain_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, martyr_id, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);

    mtgsim::mark_damage(game, martyr_id, 1);
