    require(trace.size() == 1U, "single action should export one trace row");
    require(trace.front().expected_choice_validation_source == mtgsim::LegalActionValidationSource::OfferedAction,
            "seed trace should know the pass was an offered action");
    trace.front().expected_choice_validation_source = mtgsim::LegalActionValidationSource::DirectDomainValidation;
    trace.front().expected_choice_validation_source_present = true;

    auto replay = checkpoint;
    const auto state_before = mtgsim::canonical_state_hash(replay);
    const auto journal_entries_before = mtgsim::journal_entry_count(replay);
