    require(result.actual_choice_validation_source == mtgsim::LegalActionValidationSource::OfferedAction,
            "diagnostics should report the actual validation source");
    require(mtgsim::canonical_state_hash(replay) == state_before, "validation-source mismatch should fail before StateCore mutation");
