void test_apnap_ordered_players_skips_lost_and_starts_with_active() {
    mtgsim::CardDefinition bear;
    bear.name = "APNAP Bear";
    bear.type_mask = mtgsim::TypeCreature;
    bear.printed_power = 2;
    bear.printed_toughness = 2;

    std::vector<mtgsim::CardDefinition> defs = {bear};
    std::vector<mtgsim::PlayerDeck> decks = {
        {"P1", {0}},
        {"P2", {0}},
        {"P3", {0}},
        {"P4", {0}}
    };
    auto game = mtgsim::make_game(std::move(defs), decks, 8181);
    game.active_player = mtgsim::PlayerId{3};
    mtgsim::player(game, mtgsim::PlayerId{4}).lost = true;

    const auto order = mtgsim::apnap_ordered_players(game);
    require(order.size() == 3U, "APNAP order should skip lost players");
    require(order[0] == mtgsim::PlayerId{3}, "APNAP order should start with the active player");
    require(order[1] == mtgsim::PlayerId{1}, "APNAP order should wrap in turn order after active player");
    require(order[2] == mtgsim::PlayerId{2}, "APNAP order should preserve wrapped turn order");
}

void test_choice_request_queue_metadata_roundtrips_and_guards_replay() {
    auto checkpoint = make_smoke_game();
    mtgsim::start_game(checkpoint);

    const auto queue = mtgsim::choice_request_queue(checkpoint);
    require(!queue.requests.empty(), "started smoke game should expose at least one choice request");
    require(queue.schema_version == mtgsim::kChoiceRequestQueueSchemaVersion, "choice queue should carry the current APNAP queue schema version");
    require(queue.queue_hash == mtgsim::choice_request_queue_hash(queue), "choice queue should carry its canonical APNAP hash");
    require(queue.state_hash == mtgsim::canonical_state_hash(checkpoint), "choice queue should bind the current StateCore hash once");
    require(std::all_of(queue.requests.begin(), queue.requests.end(), [&queue](const mtgsim::ChoiceRequest& request) { return request.state_hash == queue.state_hash; }), "every queued request should reuse the queue StateCore hash");
    require(queue.requests.front().chooser == checkpoint.priority_player, "priority choice should be the first APNAP queue request in the smoke game");

    auto game = checkpoint;
    const auto pass = queue.requests.front().actions.front();
    require(mtgsim::apply_action(game, pass), "seed action should apply through the queued choice boundary");
    const auto* receipt = mtgsim::latest_action_receipt_record(game);
    require(receipt != nullptr, "applied action should append a receipt");
    require(receipt->choice_queue_schema_version == mtgsim::kChoiceRequestQueueSchemaVersion, "receipt should bind the APNAP choice queue schema version");
    require(receipt->choice_queue_hash == queue.queue_hash, "receipt should bind the APNAP choice queue hash");
    require(receipt->choice_queue_index == 1U, "receipt should record the selected request index inside the APNAP queue");
    require(receipt->choice_queue_size == queue.requests.size(), "receipt should record the APNAP queue size");
    require(receipt->choice_queue_location_schema_version == mtgsim::kChoiceQueueLocationSchemaVersion, "receipt should record the APNAP queue-location schema version");
    require(receipt->choice_queue_location_checked, "receipt should mark APNAP queue proof as checked for legal actions");
    require(receipt->choice_queue_location_found, "receipt should mark the selected APNAP queue entry as found");
    require(receipt->choice_queue_location_hash != 0U, "receipt should seal the selected APNAP queue entry");
    require(receipt->choice_page_state_hash == mtgsim::canonical_state_hash(checkpoint), "receipt page context should bind to the pre-action StateCore hash");
    require(receipt->choice_page_choice_request_hash == receipt->choice_request_hash, "receipt page context should bind to the chosen request hash");

    const auto trace = mtgsim::export_action_trace(game);
    require(trace.size() == 1U, "one receipt should export one trace entry");
    require(trace.front().expected_choice_queue_schema_version == mtgsim::kChoiceRequestQueueSchemaVersion, "trace should carry the APNAP choice queue schema version");
    require(trace.front().expected_choice_queue_hash == queue.queue_hash, "trace should carry the APNAP choice queue hash");
    require(trace.front().expected_choice_queue_location_schema_version == mtgsim::kChoiceQueueLocationSchemaVersion, "trace should carry the APNAP queue-location schema version");
    require(trace.front().expected_choice_queue_location_checked, "trace should carry the checked APNAP queue-proof sentinel");
    require(trace.front().expected_choice_queue_location_found, "trace should carry the positive APNAP queue-proof sentinel");
    require(trace.front().expected_choice_queue_location_hash == receipt->choice_queue_location_hash, "trace should carry the compact APNAP queue-location hash");
    const auto parsed = mtgsim::parse_action_trace(mtgsim::serialize_action_trace(trace));
    require(parsed.ok, "trace text with APNAP metadata should parse");
    require(parsed.trace.front().expected_choice_queue_schema_version == mtgsim::kChoiceRequestQueueSchemaVersion, "trace text should preserve APNAP choice queue schema");
    require(parsed.trace.front().expected_choice_queue_hash == queue.queue_hash, "trace text should preserve APNAP queue hash");
    require(parsed.trace.front().expected_choice_queue_index == 1U, "trace text should preserve APNAP queue index");
    require(parsed.trace.front().expected_choice_queue_size == queue.requests.size(), "trace text should preserve APNAP queue size");
    require(parsed.trace.front().expected_choice_queue_location_schema_version == mtgsim::kChoiceQueueLocationSchemaVersion, "trace text should preserve the APNAP queue-location schema version");
    require(parsed.trace.front().expected_choice_queue_location_checked, "trace text should preserve the checked APNAP queue-proof sentinel");
    require(parsed.trace.front().expected_choice_queue_location_found, "trace text should preserve the positive APNAP queue-proof sentinel");
    require(parsed.trace.front().expected_choice_queue_location_hash == receipt->choice_queue_location_hash, "trace text should preserve the APNAP queue-location hash");

    auto tampered_trace = trace;
    tampered_trace.front().expected_choice_queue_hash ^= 0x8a7c11e7715e9d3bULL;
    auto replay = checkpoint;
    const auto state_before = mtgsim::canonical_state_hash(replay);
    const auto journal_entries_before = mtgsim::journal_entry_count(replay);
    const auto result = mtgsim::replay_action_trace(replay, tampered_trace);
    require(!result.ok, "replay should reject stale APNAP queue metadata");
    require(result.failure == mtgsim::ActionReplayFailureKind::ChoiceQueueHashMismatch, "replay should classify global choice queue drift separately");
    require(result.expected_choice_queue_hash == tampered_trace.front().expected_choice_queue_hash, "diagnostics should retain expected queue hash");
    require(result.actual_choice_queue_hash == queue.queue_hash, "diagnostics should report actual queue hash");
    require(mtgsim::canonical_state_hash(replay) == state_before, "queue mismatch should fail before StateCore mutation");
    require(mtgsim::journal_entry_count(replay) == journal_entries_before, "queue mismatch should fail before journal mutation");
}

