void test_replay_artifact_prefix_bundle_localizes_first_bad_action() {
    auto checkpoint = make_smoke_game();
    mtgsim::start_game(checkpoint);
    const auto snapshot_text = mtgsim::serialize_state_core_snapshot(checkpoint);

    auto final_state = checkpoint;
    for (int i = 0; i < 2; ++i) {
        mtgsim::LegalAction pass{};
        pass.kind = mtgsim::ActionKind::PassPriority;
        pass.player = final_state.priority_player;
        require(mtgsim::apply_action(final_state, pass), "prefix-localization fixture pass should apply");
    }

    auto trace = mtgsim::export_action_trace(final_state);
    require(trace.size() == 2U, "prefix-localization fixture should produce two trace entries");
    trace[1].expected_state_hash_after ^= 1U;
    const auto bad_trace_text = mtgsim::serialize_action_trace(trace);
    const auto manifest = mtgsim::make_replay_artifact_manifest(snapshot_text, bad_trace_text, final_state);

    const auto verify = mtgsim::verify_replay_artifact_bundle(snapshot_text, bad_trace_text, manifest);
    require(!verify.ok, "tampered trace should fail manifest-bound replay");
    require(verify.failure == mtgsim::ReplayArtifactFailureKind::TraceReplayFailed, "tampered trace should fail at replay, not at text hashing");
    require(verify.replay.mismatch_index == 2U, "tampered second action should be the first divergent step");

    const mtgsim::ReplayArtifactPrefixResult prefix = mtgsim::make_replay_artifact_prefix_bundle(snapshot_text, bad_trace_text, manifest);
    require(prefix.ok, "prefix bundle generation should succeed for replay-localized divergence");
    require(prefix.source_failure == mtgsim::ReplayArtifactFailureKind::TraceReplayFailed, "prefix diagnostics should retain source failure kind");
    require(prefix.prefix_action_count == 1U, "prefix should contain the longest known-good action prefix");
    require(prefix.next_bad_step == 2U, "prefix should point at the first bad next step");
    require(prefix.prefix_trace.size() == 1U, "prefix trace vector should match the prefix count");
    require(prefix.prefix_manifest.action_count == 1U, "prefix manifest should bind the reduced trace count");

    const auto prefix_verify = mtgsim::verify_replay_artifact_bundle(snapshot_text, prefix.prefix_trace_text, prefix.prefix_manifest);
    require(prefix_verify.ok, "generated prefix bundle should itself verify cleanly");
    require(prefix_verify.action_count == 1U, "verified prefix should contain one action");
    require(prefix_verify.actual_final_state_hash == prefix.prefix_final_state_hash, "prefix diagnostics should carry the verified final StateCore hash");
}

