void test_action_enumerator_respects_flying_evasion() {
    auto game = make_keyword_game();
    start_empty_unshuffled(game);
    const auto flyer = mtgsim::ObjectId{1};
    const auto ground = mtgsim::ObjectId{4};
    mtgsim::move_object(game, flyer, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, ground, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    game.step = mtgsim::Step::DeclareAttackers;
    make_ready(game, flyer);
    require(mtgsim::declare_attacker(game, mtgsim::PlayerId{1}, flyer, mtgsim::PlayerId{2}), "flying creature should attack");
    game.step = mtgsim::Step::DeclareBlockers;
    const auto actions = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{2});
    const auto nonempty_blocks = static_cast<std::size_t>(std::count_if(actions.begin(), actions.end(), [](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareBlocker && (action.object.valid() || action.target.valid() || !action.targets.empty());
    }));
    require(nonempty_blocks == 0U, "block action list should omit illegal ground block of flyer");
    require(std::any_of(actions.begin(), actions.end(), [](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareBlocker && !action.object.valid() && !action.target.valid() && action.targets.empty();
    }), "block action list should expose an explicit no-block declaration");
    mtgsim::assert_valid_game_state(game);
}

