void test_first_strike_kills_blocker_before_regular_damage() {
    auto game = make_advanced_keyword_game();
    start_empty_unshuffled(game);
    const auto duelist = mtgsim::ObjectId{1};
    const auto bear = mtgsim::ObjectId{6};
    mtgsim::move_object(game, duelist, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, bear, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    game.step = mtgsim::Step::DeclareAttackers;
    make_ready(game, duelist);
    require(mtgsim::declare_attacker(game, mtgsim::PlayerId{1}, duelist, mtgsim::PlayerId{2}), "first striker should attack");
    game.step = mtgsim::Step::DeclareBlockers;
    require(mtgsim::declare_blocker(game, mtgsim::PlayerId{2}, bear, duelist), "bear should block first striker");
    game.step = mtgsim::Step::CombatDamage;
    mtgsim::assign_combat_damage(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::object(game, duelist).zone == mtgsim::Zone::Battlefield, "first striker should survive because blocker died before regular damage");
    require(mtgsim::object(game, duelist).damage_marked == 0, "first striker should not receive regular combat damage from dead blocker");
    require(mtgsim::object(game, bear).zone == mtgsim::Zone::Graveyard, "blocker should die to first-strike damage");
    require(mtgsim::player(game, mtgsim::PlayerId{2}).life == 20, "blocked first striker should not hit defending player without trample");
}

