void test_combat_declaration_record_links_vigilance_and_menace_batch_context() {
    {
        auto game = make_keyword_game();
        start_empty_unshuffled(game);
        const auto paladin = mtgsim::ObjectId{2};
        mtgsim::move_object(game, paladin, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
        game.step = mtgsim::Step::DeclareAttackers;
        make_ready(game, paladin);
        const auto before_records = mtgsim::combat_declaration_record_count(game);
        require(mtgsim::declare_attacker(game, mtgsim::PlayerId{1}, paladin, mtgsim::PlayerId{2}), "vigilant creature should attack for declaration-record test");
        require(mtgsim::combat_declaration_record_count(game) == before_records + 1U, "attacker declaration should append a structured CombatDeclarationRecord");
        const auto* attack_record = mtgsim::latest_combat_declaration_record(game);
        require(attack_record != nullptr, "latest CombatDeclarationRecord accessor should expose attacker declaration");
        require(attack_record->kind == mtgsim::CombatDeclarationKind::Attacker, "attack declaration record should identify attacker role");
        require(attack_record->actor == paladin && attack_record->attacker == paladin, "attack declaration should preserve attacker identity");
        require(attack_record->controller == mtgsim::PlayerId{1} && attack_record->defending_player == mtgsim::PlayerId{2}, "attack declaration should snapshot controller and defender");
        require(attack_record->target.kind == mtgsim::TargetKind::Player && attack_record->target.player == mtgsim::PlayerId{2}, "player attack target should be recorded");
        require(attack_record->target_is_player && !attack_record->target_is_planeswalker && !attack_record->target_is_battle, "player attack flags should be coherent");
        require(attack_record->actor_zone_change_index != 0U && attack_record->actor_zone_change_index == mtgsim::object(game, paladin).zone_change_index, "attacker declaration should snapshot zone identity");
        require(attack_record->vigilance && !attack_record->tapped_before && !attack_record->tapped_after, "vigilance declaration should preserve untapped state");
        require(std::any_of(game.event_records.begin(), game.event_records.end(), [&](const mtgsim::EventRecord& event_record) {
            return event_record.kind == mtgsim::EventRecordKind::CombatDeclaration &&
                   event_record.combat_declaration_record_index == mtgsim::combat_declaration_record_count(game) &&
                   event_record.object == paladin;
        }), "typed EventRecord spine should link the attacker CombatDeclarationRecord");
        mtgsim::assert_valid_game_state(game);

        auto corrupted = game;
        corrupted.combat_declaration_records.back().tapped_after = true;
        const auto violations = mtgsim::validate_game_state(corrupted);
        require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& violation) {
            return violation.code == "combat_declaration_record.vigilance_tap_mismatch";
        }), "validator should reject a vigilance attack record that claims the creature tapped");
    }

    {
        auto game = make_protection_menace_game();
        start_empty_unshuffled(game);
        const auto raider = mtgsim::ObjectId{4};
        const auto goblin = mtgsim::ObjectId{5};
        const auto spider = mtgsim::ObjectId{6};
        mtgsim::move_object(game, raider, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
        mtgsim::move_object(game, goblin, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
        mtgsim::move_object(game, spider, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
        game.step = mtgsim::Step::DeclareAttackers;
        make_ready(game, raider);
        require(mtgsim::declare_attacker(game, mtgsim::PlayerId{1}, raider, mtgsim::PlayerId{2}), "menace creature should attack before batch-block declaration");
        game.step = mtgsim::Step::DeclareBlockers;
        const auto before_records = mtgsim::combat_declaration_record_count(game);
        require(mtgsim::declare_blockers(game, mtgsim::PlayerId{2}, std::vector<mtgsim::BlockAssignment>{{goblin, raider}, {spider, raider}}), "two blockers should satisfy menace as a batch");
        require(mtgsim::combat_declaration_record_count(game) == before_records + 2U, "batch declaration should append one CombatDeclarationRecord per blocker");
        const mtgsim::CombatDeclarationRecord* goblin_record = nullptr;
        const mtgsim::CombatDeclarationRecord* spider_record = nullptr;
        for (const auto& record : game.combat_declaration_records) {
            if (record.kind == mtgsim::CombatDeclarationKind::Blocker && record.blocker == goblin) {
                goblin_record = &record;
            }
            if (record.kind == mtgsim::CombatDeclarationKind::Blocker && record.blocker == spider) {
                spider_record = &record;
            }
        }
        require(goblin_record != nullptr && spider_record != nullptr, "both blockers should have declaration records");
        for (const auto* record : {goblin_record, spider_record}) {
            require(record->actor == record->blocker, "block declaration actor should be the blocker");
            require(record->target.kind == mtgsim::TargetKind::Object && record->target.object == raider, "block declaration target should be the blocked attacker");
            require(record->target_zone_change_index == mtgsim::object(game, raider).zone_change_index, "block declaration should snapshot attacker target identity");
            require(record->attacker_had_menace && record->menace_satisfied, "block declaration should snapshot satisfied menace context");
            require(record->blocker_batch_size == 2U && record->final_blocker_count_for_attacker == 2U, "block declaration should preserve batch and final blocker counts");
            require(record->attacker_marked_blocked_after, "block declaration should snapshot attacker blocked flag after batch application");
        }
        require(std::any_of(game.event_records.begin(), game.event_records.end(), [&](const mtgsim::EventRecord& event_record) {
            return event_record.kind == mtgsim::EventRecordKind::CombatDeclaration &&
                   event_record.combat_declaration_record_index != 0U &&
                   game.combat_declaration_records[event_record.combat_declaration_record_index - 1U].blocker == goblin;
        }), "typed EventRecord spine should link blocker CombatDeclarationRecords");
        mtgsim::assert_valid_game_state(game);

        auto corrupted = game;
        corrupted.combat_declaration_records.back().final_blocker_count_for_attacker = 1U;
        const auto violations = mtgsim::validate_game_state(corrupted);
        require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& violation) {
            return violation.code == "combat_declaration_record.menace_not_satisfied";
        }), "validator should reject a menace block declaration record with an underblocked final count");
    }
}

void test_combat_damage_assignment_record_links_trample_batches_to_damage_records() {
    auto game = make_advanced_keyword_game();
    start_empty_unshuffled(game);
    const auto baloth = mtgsim::ObjectId{3};
    const auto bear = mtgsim::ObjectId{6};
    mtgsim::move_object(game, baloth, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, bear, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    game.step = mtgsim::Step::DeclareAttackers;
    make_ready(game, baloth);
    require(mtgsim::declare_attacker(game, mtgsim::PlayerId{1}, baloth, mtgsim::PlayerId{2}), "trampler should attack for assignment-record test");
    game.step = mtgsim::Step::DeclareBlockers;
    require(mtgsim::declare_blocker(game, mtgsim::PlayerId{2}, bear, baloth), "bear should block trampler for assignment-record test");

    const auto before_assignment_records = mtgsim::combat_damage_assignment_record_count(game);
    const auto before_damage_records = mtgsim::damage_record_count(game);
    game.step = mtgsim::Step::CombatDamage;
    mtgsim::assign_combat_damage(game);

    require(mtgsim::combat_damage_assignment_record_count(game) == before_assignment_records + 3U, "trample combat should create attacker-to-blocker, attacker-excess, and blocker assignment records");
    require(mtgsim::latest_combat_damage_assignment_record(game) != nullptr, "latest CombatDamageAssignmentRecord accessor should expose the newest assignment");
    require(mtgsim::damage_record_count(game) == before_damage_records + 3U, "each combat assignment should link one DamageRecord");

    const mtgsim::CombatDamageAssignmentRecord* blocker_assignment = nullptr;
    const mtgsim::CombatDamageAssignmentRecord* excess_assignment = nullptr;
    for (const auto& record : game.combat_damage_assignment_records) {
        if (record.source == bear && record.source_was_blocker && record.target.kind == mtgsim::TargetKind::Object && record.target.object == baloth) {
            blocker_assignment = &record;
        }
        if (record.source == baloth && record.excess_trample && record.target.kind == mtgsim::TargetKind::Player && record.target.player == mtgsim::PlayerId{2}) {
            excess_assignment = &record;
        }
    }

    require(blocker_assignment != nullptr, "blocker damage assignment should be recorded");
    require(blocker_assignment->assigned == 2U, "bear should assign 2 combat damage back to the trampler");
    require(blocker_assignment->source_was_blocker && !blocker_assignment->source_was_attacker, "blocker assignment should snapshot source role");
    require(blocker_assignment->blocker_count == 1U, "blocker assignment should snapshot blocker count");
    require(blocker_assignment->damage_record_index != 0U, "blocker assignment should link the DamageRecord it created");

    require(excess_assignment != nullptr, "excess trample assignment should be recorded");
    require(excess_assignment->assigned == 3U, "5-power trampler should assign 3 excess damage after lethal blocker assignment");
    require(excess_assignment->source_was_attacker && !excess_assignment->source_was_blocker, "excess assignment should snapshot attacker source role");
    require(excess_assignment->source_had_trample && excess_assignment->excess_trample, "excess assignment should preserve trample routing metadata");
    require(excess_assignment->attacker_was_blocked && excess_assignment->blocker_count == 1U, "excess assignment should preserve blocked-attacker context");
    require(excess_assignment->source_zone_change_index != 0U, "excess assignment should snapshot source zone identity");
    require(excess_assignment->damage_record_index != 0U && excess_assignment->damage_record_index <= game.damage_records.size(), "excess assignment should link a valid DamageRecord");
    const auto& excess_damage = game.damage_records[excess_assignment->damage_record_index - 1U];
    require(excess_damage.source == excess_assignment->source, "linked DamageRecord should share source");
    require(excess_damage.target == excess_assignment->target, "linked DamageRecord should share target");
    require(excess_damage.amount == excess_assignment->assigned, "linked DamageRecord should preserve assigned amount");
    require(excess_damage.sequence < excess_assignment->sequence, "DamageRecord should be emitted before the combat assignment record that explains it");
    require(std::any_of(game.event_records.begin(), game.event_records.end(), [&](const mtgsim::EventRecord& event_record) {
        return event_record.kind == mtgsim::EventRecordKind::CombatDamageAssignment &&
               event_record.combat_damage_assignment_record_index != 0U &&
               &game.combat_damage_assignment_records[event_record.combat_damage_assignment_record_index - 1U] == excess_assignment;
    }), "typed EventRecord spine should link the CombatDamageAssignmentRecord");
    mtgsim::assert_valid_game_state(game);

    auto bad_damage_link = game;
    bad_damage_link.combat_damage_assignment_records.back().damage_record_index = 0U;
    const auto bad_damage_link_violations = mtgsim::validate_game_state(bad_damage_link);
    require(std::any_of(bad_damage_link_violations.begin(), bad_damage_link_violations.end(), [](const mtgsim::InvariantViolation& violation) {
        return violation.code == "combat_damage_assignment_record.invalid_damage_link";
    }), "validator should reject a combat assignment record with no valid DamageRecord link");

    auto bad_event_link = game;
    for (auto& event_record : bad_event_link.event_records) {
        if (event_record.kind == mtgsim::EventRecordKind::CombatDamageAssignment) {
            event_record.combat_damage_assignment_record_index = 0U;
            break;
        }
    }
    const auto bad_event_link_violations = mtgsim::validate_game_state(bad_event_link);
    require(std::any_of(bad_event_link_violations.begin(), bad_event_link_violations.end(), [](const mtgsim::InvariantViolation& violation) {
        return violation.code == "event_record.invalid_combat_damage_assignment_link";
    }), "validator should reject a combat assignment EventRecord with a broken typed link");
}

void test_trample_assigns_excess_damage_to_defending_player() {
    auto game = make_advanced_keyword_game();
    start_empty_unshuffled(game);
    const auto baloth = mtgsim::ObjectId{3};
    const auto bear = mtgsim::ObjectId{6};
    mtgsim::move_object(game, baloth, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, bear, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    game.step = mtgsim::Step::DeclareAttackers;
    make_ready(game, baloth);
    require(mtgsim::declare_attacker(game, mtgsim::PlayerId{1}, baloth, mtgsim::PlayerId{2}), "trampler should attack");
    game.step = mtgsim::Step::DeclareBlockers;
    require(mtgsim::declare_blocker(game, mtgsim::PlayerId{2}, bear, baloth), "bear should block trampler");
    game.step = mtgsim::Step::CombatDamage;
    mtgsim::assign_combat_damage(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::object(game, bear).zone == mtgsim::Zone::Graveyard, "blocker should receive lethal trample assignment");
    require(mtgsim::object(game, baloth).zone == mtgsim::Zone::Battlefield, "trampler should survive blocker damage");
    require(mtgsim::object(game, baloth).damage_marked == 2, "blocker damage should still be marked on trampler");
    require(mtgsim::player(game, mtgsim::PlayerId{2}).life == 17, "5-power trampler should assign 2 lethal to blocker and 3 excess to defender");
}

