void test_indestructible_survives_lethal_and_deathtouch_damage() {
    auto game = make_advanced_keyword_game();
    start_empty_unshuffled(game);
    const auto monument = mtgsim::ObjectId{4};
    const auto venom = mtgsim::ObjectId{5};
    mtgsim::move_object(game, monument, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, venom, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    require(mtgsim::object_has_ability(game, monument, mtgsim::AbilityIndestructible), "setup should give monument indestructible");
    mtgsim::mark_damage(game, monument, 2);
    mtgsim::apply_state_based_actions(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::object(game, monument).zone == mtgsim::Zone::Battlefield, "indestructible creature should survive lethal marked damage");
    mtgsim::deal_damage_to_target(game, venom, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = monument}, 1);
    mtgsim::apply_state_based_actions(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::object(game, monument).zone == mtgsim::Zone::Battlefield, "indestructible creature should survive deathtouch damage");
    mtgsim::add_counter_to_object(game, monument, mtgsim::CounterKind::MinusOneMinusOne, 2);
    mtgsim::apply_state_based_actions(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::object(game, monument).zone == mtgsim::Zone::Graveyard, "indestructible does not save a creature from non-positive toughness in this scaffold");
}


