void test_defender_cannot_attack_even_when_ready() {
    auto game = make_summoning_and_targeting_game();
    start_empty_unshuffled(game);
    const auto wall = mtgsim::ObjectId{3};
    mtgsim::move_object(game, wall, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    make_ready(game, wall);
    game.step = mtgsim::Step::DeclareAttackers;
    require(mtgsim::object_has_ability(game, wall, mtgsim::AbilityDefender), "setup should give wall defender");
    require(!mtgsim::can_declare_attacker(game, mtgsim::PlayerId{1}, wall, mtgsim::PlayerId{2}), "defender creature should not attack");
    const auto actions = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{1});
    const auto nonempty_attacks = static_cast<std::size_t>(std::count_if(actions.begin(), actions.end(), [](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareAttacker && (action.object.valid() || action.target.valid() || !action.targets.empty());
    }));
    require(nonempty_attacks == 0U, "attack action list should omit defender-only nonempty attack options");
    const auto empty_declaration = std::find_if(actions.begin(), actions.end(), [](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareAttacker && !action.object.valid() && !action.target.valid() && action.targets.empty();
    });
    require(empty_declaration != actions.end(), "attack action list should expose an explicit no-attack declaration");
    require(mtgsim::apply_action(game, *empty_declaration), "explicit no-attack declaration should apply");
    require(game.attackers_declared_this_step, "explicit no-attack declaration should close the attacker declaration window");
    const auto after_empty = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{1});
    require(std::none_of(after_empty.begin(), after_empty.end(), [](const mtgsim::LegalAction& action) { return action.kind == mtgsim::ActionKind::DeclareAttacker; }),
            "attacker declaration window should not reopen after explicit empty declaration");
    mtgsim::assert_valid_game_state(game);
}

