void test_validation_catches_summoning_sick_and_defender_attack_metadata() {
    auto game = make_summoning_and_targeting_game();
    start_empty_unshuffled(game);
    const auto recruit = mtgsim::ObjectId{1};
    const auto wall = mtgsim::ObjectId{3};
    mtgsim::move_object(game, recruit, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, wall, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    game.step = mtgsim::Step::DeclareAttackers;
    mtgsim::object(game, recruit).attacking = true;
    mtgsim::object(game, recruit).defending_player = mtgsim::PlayerId{2};
    mtgsim::object(game, wall).attacking = true;
    mtgsim::object(game, wall).defending_player = mtgsim::PlayerId{2};
    const auto violations = mtgsim::validate_game_state(game);
    require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& v) { return v.code == "combat.summoning_sick_attacker"; }), "validator should reject summoning-sick attacker metadata");
    require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& v) { return v.code == "combat.defender_attacking"; }), "validator should reject defender attacker metadata");
}

void test_hexproof_filters_opposing_targeting_but_allows_controller() {
    auto game = make_summoning_and_targeting_game();
    start_empty_unshuffled(game);
    const auto bolt = mtgsim::ObjectId{6};
    const auto hexproof = mtgsim::ObjectId{8};
    mtgsim::move_object(game, bolt, mtgsim::PlayerId{1}, mtgsim::Zone::Hand);
    mtgsim::move_object(game, hexproof, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    mtgsim::add_mana(game, mtgsim::PlayerId{1}, mtgsim::ManaSymbol::Red);
    const auto target = mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = hexproof};
    require(!mtgsim::target_ref_is_legal_for_source(game, target, mtgsim::TargetObject, mtgsim::PlayerId{1}), "opponent-controlled spell should not target hexproof creature");
    require(mtgsim::target_ref_is_legal_for_source(game, target, mtgsim::TargetObject, mtgsim::PlayerId{2}), "controller should be able to target their own hexproof creature");
    const auto actions = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{1});
    require(!has_action(actions, mtgsim::ActionKind::CastSpellFromHandPaid, bolt, target), "legal-action mask should omit opposing hexproof target");
    mtgsim::assert_valid_game_state(game);
}

