void test_protection_from_red_filters_source_aware_targeting() {
    auto game = make_protection_menace_game();
    start_empty_unshuffled(game);
    const auto red_bolt = mtgsim::ObjectId{1};
    const auto green_growth = mtgsim::ObjectId{2};
    const auto knight = mtgsim::ObjectId{3};
    mtgsim::move_object(game, red_bolt, mtgsim::PlayerId{1}, mtgsim::Zone::Hand);
    mtgsim::move_object(game, green_growth, mtgsim::PlayerId{1}, mtgsim::Zone::Hand);
    mtgsim::move_object(game, knight, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    const auto target = mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = knight};
    require(mtgsim::object_has_protection_from_color(game, knight, mtgsim::ColorRed), "setup should give knight protection from red");
    require(!mtgsim::target_ref_is_legal_for_source_object(game, target, mtgsim::TargetObject, red_bolt), "red spell source should not target a creature with protection from red");
    require(mtgsim::target_ref_is_legal_for_source_object(game, target, mtgsim::TargetObject, green_growth), "green spell source should still be able to target protection-from-red creature");
    mtgsim::add_mana(game, mtgsim::PlayerId{1}, mtgsim::ManaSymbol::Red);
    const auto red_actions = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{1});
    require(!has_action(red_actions, mtgsim::ActionKind::CastSpellFromHandPaid, red_bolt, target), "legal-action mask should omit protected object from red spell variants");
    mtgsim::clear_mana_pool(game, mtgsim::PlayerId{1});
    mtgsim::add_mana(game, mtgsim::PlayerId{1}, mtgsim::ManaSymbol::Green);
    require(mtgsim::cast_from_hand_to_stack_paying_mana_with_target(game, mtgsim::PlayerId{1}, green_growth, target), "non-red targeted growth spell should cast onto protected creature");
    mtgsim::pass_priority(game);
    mtgsim::pass_priority(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::object_counter_count(game, knight, mtgsim::CounterKind::PlusOnePlusOne) == 1U, "green effect should resolve onto protection-from-red target");
}

