void test_menace_requires_two_blockers_and_batch_declaration_supports_it() {
    auto game = make_protection_menace_game();
    start_empty_unshuffled(game);
    const auto raider = mtgsim::ObjectId{4};
    const auto bear_a = mtgsim::ObjectId{7};
    const auto bear_b = mtgsim::ObjectId{8};
    mtgsim::move_object(game, raider, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, bear_a, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, bear_b, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    game.step = mtgsim::Step::DeclareAttackers;
    make_ready(game, raider);
    require(mtgsim::object_has_ability(game, raider, mtgsim::AbilityMenace), "setup should give raider menace");
    require(mtgsim::declare_attacker(game, mtgsim::PlayerId{1}, raider, mtgsim::PlayerId{2}), "menace creature should attack");
    game.step = mtgsim::Step::DeclareBlockers;
    require(!mtgsim::can_declare_blocker(game, mtgsim::PlayerId{2}, bear_a, raider), "single blocker should not satisfy menace");
    const std::vector<mtgsim::BlockAssignment> pair = {
        {.blocker = bear_a, .attacker = raider},
        {.blocker = bear_b, .attacker = raider}
    };
    require(mtgsim::can_declare_blockers(game, mtgsim::PlayerId{2}, pair), "two-blocker batch should satisfy menace");

    const auto checkpoint = game;
    const auto actions = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{2});
    const auto it = std::find_if(actions.begin(), actions.end(), [&](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareBlocker &&
               action.object == mtgsim::ObjectId{} &&
               mtgsim::block_assignments_from_action(action) == pair;
    });
    require(it != actions.end(), "public LegalAction enumeration should expose the two-blocker menace batch");
    require(it->targets.size() == 4U, "batch blocker action should encode blocker/attacker pairs in the replay target vector");
    require(mtgsim::canonical_action_string(*it).find("targets=4[") != std::string::npos, "canonical action string should bind the full blocker batch");

    require(mtgsim::apply_action(game, *it), "batch block action should commit through the replayable action boundary");
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::object(game, raider).blocked, "menace attacker should be marked blocked after legal two-blocker batch");
    require(mtgsim::object(game, bear_a).blocking == raider && mtgsim::object(game, bear_b).blocking == raider, "both blockers should point at the menace attacker");

    const auto* receipt = mtgsim::latest_action_receipt_record(game);
    require(receipt != nullptr, "batch block apply should append an action receipt");
    require(receipt->kind == mtgsim::ActionKind::DeclareBlocker, "receipt should preserve the declare-blocker action kind");
    require(receipt->targets.size() == 4U, "receipt should persist all blocker/attacker pair targets");
    require(receipt->choice_kind == mtgsim::ChoiceRequestKind::DeclareBlockers, "receipt should classify the batch as a blocker declaration choice");

    const auto trace = mtgsim::export_action_trace(game);
    require(trace.size() == 1U, "single batch block action should export one replay step");
    require(mtgsim::block_assignments_from_action(trace.front().action) == pair, "trace action should reconstruct the same blocker batch");

    auto replay = checkpoint;
    const auto replay_result = mtgsim::replay_action_trace(replay, trace);
    require(replay_result.ok, "batch block action trace should replay from the declaration checkpoint");
    require(mtgsim::canonical_state_hash(replay) == mtgsim::canonical_state_hash(game), "replayed batch block should reach the same StateCore");
    require(mtgsim::object(replay, bear_a).blocking == raider && mtgsim::object(replay, bear_b).blocking == raider, "replayed batch block should restore both assignments");
}

void test_combat_attack_requirement_filters_empty_and_subset_declarations() {
    auto game = make_combat_requirement_game();
    start_empty_unshuffled(game);
    const auto alpha_library = mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Library);
    require(alpha_library.size() >= 2U, "requirement fixture should provide required and optional attackers");
    const auto required_attacker = alpha_library[0];
    const auto optional_attacker = alpha_library[1];
    mtgsim::move_object(game, required_attacker, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, optional_attacker, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    make_ready(game, required_attacker);
    make_ready(game, optional_attacker);
    game.step = mtgsim::Step::DeclareAttackers;
    game.active_player = mtgsim::PlayerId{1};
    game.priority_player = mtgsim::PlayerId{1};

    const auto defend_beta = mtgsim::TargetRef{.kind = mtgsim::TargetKind::Player, .player = mtgsim::PlayerId{2}};
    const std::vector<mtgsim::AttackAssignment> required_only{{.attacker = required_attacker, .target = defend_beta}};
    const std::vector<mtgsim::AttackAssignment> optional_only{{.attacker = optional_attacker, .target = defend_beta}};
    const std::vector<mtgsim::AttackAssignment> both{{.attacker = required_attacker, .target = defend_beta}, {.attacker = optional_attacker, .target = defend_beta}};

    require(!mtgsim::can_declare_attackers(game, mtgsim::PlayerId{1}, {}), "empty attack declaration should be illegal when a must-attack creature can attack");
    require(!mtgsim::can_declare_attackers(game, mtgsim::PlayerId{1}, optional_only), "subset missing the must-attack creature should be illegal");
    require(mtgsim::can_declare_attackers(game, mtgsim::PlayerId{1}, required_only), "declaring the must-attack creature should satisfy the requirement");
    require(mtgsim::can_declare_attackers(game, mtgsim::PlayerId{1}, both), "declaring optional attackers in addition to the required attacker should be legal");

    const auto checkpoint = game;
    const auto actions = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{1});
    require(std::none_of(actions.begin(), actions.end(), [](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareAttacker && mtgsim::attack_assignments_from_action(action).empty();
    }), "enumeration should not expose declare_attackers:none while an attack requirement is unsatisfied");
    require(std::none_of(actions.begin(), actions.end(), [&](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareAttacker && mtgsim::attack_assignments_from_action(action) == optional_only;
    }), "enumeration should not expose attack batches missing a required attacker");
    const auto required_it = std::find_if(actions.begin(), actions.end(), [&](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareAttacker && mtgsim::attack_assignments_from_action(action) == required_only;
    });
    require(required_it != actions.end(), "enumeration should expose the minimal required attack batch");

    require(mtgsim::apply_action(game, *required_it), "required attack declaration should apply through the public action boundary");
    require(mtgsim::object(game, required_attacker).attacking, "must-attack creature should be attacking after commit");
    require(!mtgsim::object(game, optional_attacker).attacking, "optional attacker may remain back after the requirement is satisfied");
    const auto* receipt = mtgsim::latest_action_receipt_record(game);
    require(receipt != nullptr && receipt->choice_kind == mtgsim::ChoiceRequestKind::DeclareAttackers, "must-attack declaration should be receipt-classified as an attack choice");

    auto replay = checkpoint;
    const auto trace = mtgsim::export_action_trace(game);
    const auto replay_result = mtgsim::replay_action_trace(replay, trace);
    require(replay_result.ok, "must-attack declaration trace should replay from checkpoint");
    require(mtgsim::canonical_state_hash(replay) == mtgsim::canonical_state_hash(game), "replayed must-attack declaration should reach the same StateCore");
}

void test_combat_attack_requirements_maximize_under_attack_limit() {
    auto game = make_combat_requirement_game();
    start_empty_unshuffled(game);
    const auto alpha_library = mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Library);
    require(alpha_library.size() >= 4U, "requirement fixture should provide attackers and an arbiter");
    const auto required_a = alpha_library[0];
    const auto optional_attacker = alpha_library[1];
    const auto arbiter = alpha_library[3];
    const auto required_b = mtgsim::create_token(game, mtgsim::PlayerId{1}, 0U);
    mtgsim::move_object(game, required_a, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, optional_attacker, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, arbiter, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    make_ready(game, required_a);
    make_ready(game, required_b);
    make_ready(game, optional_attacker);
    game.step = mtgsim::Step::DeclareAttackers;
    game.active_player = mtgsim::PlayerId{1};
    game.priority_player = mtgsim::PlayerId{1};

    const auto defend_beta = mtgsim::TargetRef{.kind = mtgsim::TargetKind::Player, .player = mtgsim::PlayerId{2}};
    const std::vector<mtgsim::AttackAssignment> required_a_only{{.attacker = required_a, .target = defend_beta}};
    const std::vector<mtgsim::AttackAssignment> required_b_only{{.attacker = required_b, .target = defend_beta}};
    const std::vector<mtgsim::AttackAssignment> optional_only{{.attacker = optional_attacker, .target = defend_beta}};
    const std::vector<mtgsim::AttackAssignment> both_required{{.attacker = required_a, .target = defend_beta}, {.attacker = required_b, .target = defend_beta}};

    require(!mtgsim::can_declare_attackers(game, mtgsim::PlayerId{1}, {}), "empty attack declaration should still miss the maximum satisfiable attack requirement count");
    require(!mtgsim::can_declare_attackers(game, mtgsim::PlayerId{1}, optional_only), "optional-only attack should not satisfy a required slot under the one-attacker limit");
    require(mtgsim::can_declare_attackers(game, mtgsim::PlayerId{1}, required_a_only), "either required attacker should satisfy the maximum possible requirements under the limit");
    require(mtgsim::can_declare_attackers(game, mtgsim::PlayerId{1}, required_b_only), "the token required attacker should also be a legal maximizing declaration");
    require(!mtgsim::can_declare_attackers(game, mtgsim::PlayerId{1}, both_required), "two required attackers should violate the active max-attackers restriction");

    const auto checkpoint = game;
    const auto actions = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{1});
    require(std::none_of(actions.begin(), actions.end(), [&](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareAttacker && mtgsim::attack_assignments_from_action(action) == optional_only;
    }), "enumeration should omit optional-only declarations when a required slot is satisfiable");
    require(std::none_of(actions.begin(), actions.end(), [&](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareAttacker && mtgsim::attack_assignments_from_action(action) == both_required;
    }), "enumeration should omit batches over the attack restriction limit");
    const auto required_it = std::find_if(actions.begin(), actions.end(), [&](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareAttacker && mtgsim::attack_assignments_from_action(action) == required_b_only;
    });
    require(required_it != actions.end(), "enumeration should expose a singleton required attacker as a maximizing declaration under the limit");

    require(mtgsim::apply_action(game, *required_it), "maximizing limited attack declaration should apply through LegalAction");
    require(mtgsim::object(game, required_b).attacking, "chosen required token should attack after commit");
    require(!mtgsim::object(game, required_a).attacking, "the unsatisfied required attacker is legal to leave back only because the restriction limit is exhausted");

    auto replay = checkpoint;
    const auto trace = mtgsim::export_action_trace(game);
    const auto replay_result = mtgsim::replay_action_trace(replay, trace);
    require(replay_result.ok, "limited maximizing attack trace should replay from checkpoint");
    require(mtgsim::canonical_state_hash(replay) == mtgsim::canonical_state_hash(game), "replayed limited attack declaration should reach the same StateCore");
}


void test_combat_attack_requirements_treat_cant_attack_alone_as_global_restriction() {
    auto game = make_combat_requirement_game();
    game.definitions[0].cant_attack_alone = true;
    start_empty_unshuffled(game);
    const auto alpha_library = mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Library);
    require(alpha_library.size() >= 2U, "requirement fixture should provide required and optional attackers");
    const auto required_attacker = alpha_library[0];
    const auto optional_attacker = alpha_library[1];
    mtgsim::move_object(game, required_attacker, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, optional_attacker, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    make_ready(game, required_attacker);
    make_ready(game, optional_attacker);
    game.step = mtgsim::Step::DeclareAttackers;
    game.active_player = mtgsim::PlayerId{1};
    game.priority_player = mtgsim::PlayerId{1};

    const auto defend_beta = mtgsim::TargetRef{.kind = mtgsim::TargetKind::Player, .player = mtgsim::PlayerId{2}};
    const std::vector<mtgsim::AttackAssignment> required_only{{.attacker = required_attacker, .target = defend_beta}};
    const std::vector<mtgsim::AttackAssignment> optional_only{{.attacker = optional_attacker, .target = defend_beta}};
    const std::vector<mtgsim::AttackAssignment> both{{.attacker = required_attacker, .target = defend_beta}, {.attacker = optional_attacker, .target = defend_beta}};

    require(!mtgsim::can_declare_attackers(game, mtgsim::PlayerId{1}, {}), "no-attack should be illegal because the required attacker can satisfy its restriction with a partner");
    require(!mtgsim::can_declare_attackers(game, mtgsim::PlayerId{1}, required_only), "the required attacker cannot attack alone even though it must attack if able");
    require(!mtgsim::can_declare_attackers(game, mtgsim::PlayerId{1}, optional_only), "optional-only should miss the maximum satisfiable attack requirement");
    require(mtgsim::can_declare_attackers(game, mtgsim::PlayerId{1}, both), "required attacker plus an optional partner should satisfy both the restriction and the requirement");

    const auto checkpoint = game;
    const auto actions = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{1});
    require(std::none_of(actions.begin(), actions.end(), [&](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareAttacker && mtgsim::attack_assignments_from_action(action) == required_only;
    }), "enumeration should omit the illegal singleton required attacker");
    const auto pair_it = std::find_if(actions.begin(), actions.end(), [&](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareAttacker && mtgsim::attack_assignments_from_action(action) == both;
    });
    require(pair_it != actions.end(), "enumeration should expose the required attacker with its legal partner");
    require(mtgsim::apply_action(game, *pair_it), "partnered attack declaration should apply through LegalAction");
    require(mtgsim::object(game, required_attacker).attacking && mtgsim::object(game, optional_attacker).attacking, "both attackers should commit atomically");

    auto replay = checkpoint;
    const auto trace = mtgsim::export_action_trace(game);
    const auto replay_result = mtgsim::replay_action_trace(replay, trace);
    require(replay_result.ok, "cant-attack-alone partnered trace should replay from checkpoint");
    require(mtgsim::canonical_state_hash(replay) == mtgsim::canonical_state_hash(game), "replayed partnered attack should reach the same StateCore");

    auto solo = make_combat_requirement_game();
    solo.definitions[0].cant_attack_alone = true;
    start_empty_unshuffled(solo);
    const auto solo_required = mtgsim::zone(solo, mtgsim::PlayerId{1}, mtgsim::Zone::Library)[0];
    mtgsim::move_object(solo, solo_required, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    make_ready(solo, solo_required);
    solo.step = mtgsim::Step::DeclareAttackers;
    solo.active_player = mtgsim::PlayerId{1};
    solo.priority_player = mtgsim::PlayerId{1};
    const std::vector<mtgsim::AttackAssignment> solo_required_only{{.attacker = solo_required, .target = defend_beta}};
    require(!mtgsim::can_declare_attackers(solo, mtgsim::PlayerId{1}, solo_required_only), "required creature cannot attack alone when no partner exists");
    require(mtgsim::can_declare_attackers(solo, mtgsim::PlayerId{1}, {}), "no-attack becomes legal because zero attack requirements are satisfiable without a partner");
}

void test_combat_block_requirement_filters_empty_and_subset_declarations() {
    auto game = make_combat_requirement_game();
    start_empty_unshuffled(game);
    const auto alpha_library = mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Library);
    const auto beta_library = mtgsim::zone(game, mtgsim::PlayerId{2}, mtgsim::Zone::Library);
    require(alpha_library.size() >= 2U && beta_library.size() >= 2U, "requirement fixture should provide attackers and blockers");
    const auto attacker = alpha_library[1];
    const auto required_blocker = beta_library[0];
    const auto optional_blocker = beta_library[1];
    mtgsim::move_object(game, attacker, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, required_blocker, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, optional_blocker, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    make_ready(game, attacker);
    game.step = mtgsim::Step::DeclareAttackers;
    game.active_player = mtgsim::PlayerId{1};
    require(mtgsim::declare_attacker(game, mtgsim::PlayerId{1}, attacker, mtgsim::PlayerId{2}), "setup attack should succeed");
    mtgsim::advance_step(game);
    require(game.step == mtgsim::Step::DeclareBlockers, "setup should reach declare blockers");

    const std::vector<mtgsim::BlockAssignment> required_only{{.blocker = required_blocker, .attacker = attacker}};
    const std::vector<mtgsim::BlockAssignment> optional_only{{.blocker = optional_blocker, .attacker = attacker}};
    const std::vector<mtgsim::BlockAssignment> both{{.blocker = required_blocker, .attacker = attacker}, {.blocker = optional_blocker, .attacker = attacker}};
    require(!mtgsim::can_declare_blockers(game, mtgsim::PlayerId{2}, {}), "empty block declaration should be illegal when a must-block creature can block");
    require(!mtgsim::can_declare_blockers(game, mtgsim::PlayerId{2}, optional_only), "subset missing the must-block creature should be illegal");
    require(mtgsim::can_declare_blockers(game, mtgsim::PlayerId{2}, required_only), "declaring the must-block creature should satisfy the requirement");
    require(mtgsim::can_declare_blockers(game, mtgsim::PlayerId{2}, both), "additional optional blockers should remain legal");

    const auto actions = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{2});
    require(std::none_of(actions.begin(), actions.end(), [](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareBlocker && mtgsim::block_assignments_from_action(action).empty();
    }), "enumeration should not expose declare_blockers:none while a block requirement is unsatisfied");
    require(std::none_of(actions.begin(), actions.end(), [&](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareBlocker && mtgsim::block_assignments_from_action(action) == optional_only;
    }), "enumeration should not expose block batches missing a required blocker");
    const auto required_it = std::find_if(actions.begin(), actions.end(), [&](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareBlocker && mtgsim::block_assignments_from_action(action) == required_only;
    });
    require(required_it != actions.end(), "enumeration should expose the minimal required block batch");
    require(mtgsim::apply_action(game, *required_it), "required block declaration should apply through the public action boundary");
    require(mtgsim::object(game, required_blocker).blocking == attacker, "must-block creature should point at the attacker after commit");
    require(!mtgsim::object(game, optional_blocker).blocking.valid(), "optional blocker may remain unassigned after the requirement is satisfied");
}

