    const std::vector<mtgsim::BlockAssignment> pair{{.blocker = blocker_a, .attacker = menace_attacker}, {.blocker = blocker_b, .attacker = menace_attacker}};
    require(!mtgsim::can_declare_blockers(game, mtgsim::PlayerId{2}, single), "single blocker still cannot satisfy menace");
    require(!mtgsim::can_declare_blockers(game, mtgsim::PlayerId{2}, pair), "complete menace pair should violate the attacker's one-blocker cap");
    require(mtgsim::can_declare_blockers(game, mtgsim::PlayerId{2}, {}), "no-block becomes legal because zero must-be-blocked requirements are satisfiable under menace plus the per-attacker cap");

    const auto actions = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{2});
