void test_regeneration_shields_expire_on_cleanup_and_zone_change() {
    auto game = make_destruction_game();
    start_empty_unshuffled(game);
    const auto bear = mtgsim::ObjectId{3};
    mtgsim::move_object(game, bear, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    mtgsim::add_regeneration_shield(game, bear, 2);
    require(mtgsim::regeneration_shield_count(game, bear) == 2, "setup should create two shields");
    game.step = mtgsim::Step::Cleanup;
    mtgsim::advance_step(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::regeneration_shield_count(game, bear) == 0, "cleanup should expire regeneration shields");
    mtgsim::add_regeneration_shield(game, bear, 1);
    mtgsim::move_object(game, bear, mtgsim::PlayerId{2}, mtgsim::Zone::Graveyard);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::regeneration_shield_count(game, bear) == 0, "zone change should clear regeneration shields");
}

void test_validation_catches_regeneration_shield_outside_battlefield() {
    auto game = make_destruction_game();
    start_empty_unshuffled(game);
    const auto bear = mtgsim::ObjectId{3};
    mtgsim::object(game, bear).regeneration_shields = 1;
    const auto violations = mtgsim::validate_game_state(game);
    require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& v) { return v.code == "object.regeneration_outside_battlefield"; }), "validator should reject regeneration shields on non-battlefield objects");
}

void test_aura_spell_enters_attached_and_grants_bonus_ability() {
    auto game = make_attachment_game();
    start_empty_unshuffled(game);
    const auto bear = mtgsim::ObjectId{1};
    const auto wings = mtgsim::ObjectId{2};
    mtgsim::move_object(game, bear, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, wings, mtgsim::PlayerId{1}, mtgsim::Zone::Hand);
    mtgsim::add_mana(game, mtgsim::PlayerId{1}, mtgsim::ManaSymbol::Blue);
    require(mtgsim::cast_from_hand_to_stack_paying_mana_with_target(game, mtgsim::PlayerId{1}, wings, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = bear}), "Aura spell should require and accept a legal enchant target");
    mtgsim::pass_priority(game);
    mtgsim::pass_priority(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::object(game, wings).zone == mtgsim::Zone::Battlefield, "resolved Aura should enter battlefield");
    require(mtgsim::object_attachment_target(game, wings) == mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = bear}, "Aura should be attached to chosen target");
    require(mtgsim::effective_power(game, bear) == 3 && mtgsim::effective_toughness(game, bear) == 3, "Aura bonus should affect effective P/T");
    require(mtgsim::object_has_ability(game, bear, mtgsim::AbilityFlying), "Aura should grant flying through object_has_ability");
}

