void test_token_sacrifice_queues_dies_trigger_then_token_ceases_on_sba() {
    auto game = make_token_lifecycle_game();
    start_empty_unshuffled(game);
    const auto artist = mtgsim::ObjectId{4};
    mtgsim::move_object(game, artist, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    const auto token = mtgsim::create_token(game, mtgsim::PlayerId{1}, 0);
    require(mtgsim::sacrifice_permanent(game, mtgsim::PlayerId{1}, token), "token permanent should be sacrificeable by its controller");
    require(mtgsim::pending_trigger_count(game) == 1U, "token dying should queue dies trigger before it ceases to exist");
    require(mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Graveyard).size() == 1U, "token should briefly be in graveyard before SBA");
    require(!mtgsim::object_ceased_to_exist(game, token), "token should not cease until state-based actions run");
    mtgsim::apply_state_based_actions(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::object_ceased_to_exist(game, token), "token should cease to exist during SBA outside battlefield");
    require(mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Graveyard).empty(), "ceased token should be removed from graveyard container");
    mtgsim::put_pending_triggers_on_stack(game);
    mtgsim::pass_priority(game);
    mtgsim::pass_priority(game);
    require(mtgsim::player(game, mtgsim::PlayerId{1}).life == 21, "dies trigger queued before token ceased should still resolve");
}

