    self_replacement.name = "exile itself";
    self_replacement.scope = mtgsim::StaticEffectScope::Source;
    self_replacement.from_zone = mtgsim::Zone::Battlefield;
    self_replacement.to_zone = mtgsim::Zone::Graveyard;
    self_replacement.replacement_zone = mtgsim::Zone::Exile;
    self_replacement.affected_type_mask = mtgsim::TypeCreature;
    phoenix.zone_change_replacements.push_back(self_replacement);

    mtgsim::CardDefinition bear;
    bear.name = "Ordinary Bear";
    bear.type_mask = mtgsim::TypeCreature;
    bear.printed_power = 2;
    bear.printed_toughness = 2;

    std::vector<mtgsim::CardDefinition> defs = {phoenix, bear};
    std::vector<mtgsim::PlayerDeck> decks = {
        {"Alpha", {0, 1}},
        {"Beta", {}}
    };
    auto game = mtgsim::make_game(std::move(defs), decks, 61436);
    start_empty_unshuffled(game);

    const auto phoenix_id = mtgsim::ObjectId{1};
    const auto bear_id = mtgsim::ObjectId{2};
    mtgsim::move_object(game, phoenix_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, bear_id, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);

    mtgsim::move_object(game, bear_id, mtgsim::PlayerId{1}, mtgsim::Zone::Graveyard);
    require(mtgsim::object(game, bear_id).zone == mtgsim::Zone::Graveyard, "source-scoped replacement should not affect a different creature");
