void test_combat_can_attack_planeswalker_and_remove_loyalty() {
    auto game = make_planeswalker_game();
    start_empty_unshuffled(game);
    const auto attacker = mtgsim::ObjectId{3};
    const auto walker = mtgsim::ObjectId{5};
    mtgsim::move_object(game, attacker, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, walker, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    make_ready(game, attacker);
    game.step = mtgsim::Step::DeclareAttackers;
    game.active_player = mtgsim::PlayerId{1};
    game.priority_player = mtgsim::PlayerId{1};
    require(mtgsim::declare_attacker_to_target(game, mtgsim::PlayerId{1}, attacker, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = walker}), "attacker should be able to attack opposing planeswalker");
    require(mtgsim::object(game, attacker).defending_player == mtgsim::PlayerId{2}, "defending player should be planeswalker's controller");
    require(mtgsim::object(game, attacker).attacked_object == walker, "attacker should remember attacked planeswalker object");
    game.step = mtgsim::Step::CombatDamage;
    mtgsim::assign_combat_damage(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::planeswalker_loyalty(game, walker) == 2U, "unblocked combat damage should remove loyalty from attacked planeswalker");
    require(mtgsim::player(game, mtgsim::PlayerId{2}).life == 20, "combat damage to planeswalker should not damage defending player");
}

void test_loyalty_ability_timing_cost_once_per_turn_and_resolution() {
    auto game = make_planeswalker_game();
    start_empty_unshuffled(game);
    const auto walker = mtgsim::ObjectId{1};
    mtgsim::move_object(game, walker, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    game.step = mtgsim::Step::Main1;
    game.active_player = mtgsim::PlayerId{1};
    game.priority_player = mtgsim::PlayerId{1};
    const auto target = mtgsim::TargetRef{.kind = mtgsim::TargetKind::Player, .player = mtgsim::PlayerId{2}};
    require(mtgsim::can_activate_loyalty_ability(game, mtgsim::PlayerId{1}, walker, target), "loyalty ability should be legal in controller's main phase with empty stack");
    require(mtgsim::activate_loyalty_ability(game, mtgsim::PlayerId{1}, walker, target), "loyalty ability activation should succeed");
    require(mtgsim::planeswalker_loyalty(game, walker) == 5U, "+1 loyalty cost should add a loyalty counter immediately");
    require(game.stack.size() == 1U, "loyalty ability should use the stack");
    require(!mtgsim::can_activate_loyalty_ability(game, mtgsim::PlayerId{1}, walker, target), "same planeswalker should not activate another loyalty ability this turn");
    mtgsim::pass_priority(game);
    mtgsim::pass_priority(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::player(game, mtgsim::PlayerId{2}).life == 18, "loyalty ability damage should resolve from stack");
}

