void test_damage_to_battle_removes_defense_and_zero_defense_sba() {
    auto game = make_battle_game();
    start_empty_unshuffled(game);
    const auto battle = mtgsim::ObjectId{1};
    const auto source = mtgsim::ObjectId{2};
    mtgsim::move_object(game, battle, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, source, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    const auto damage_counter_change_records_before = mtgsim::counter_change_record_count(game);
    mtgsim::deal_damage_to_target(game, source, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = battle}, 3);
    require(mtgsim::battle_defense(game, battle) == 1U, "damage to a battle should remove defense counters");
    require(mtgsim::player(game, mtgsim::PlayerId{1}).life == 20, "damage to battle should not reduce controller life");
    const auto* first_damage = mtgsim::latest_damage_record(game);
    require(first_damage != nullptr && first_damage->target_was_battle, "battle damage should append a battle-target DamageRecord");
    require(first_damage->counters_removed == 3U, "DamageRecord should preserve removed defense count");
    require(first_damage->first_damage_counter_change_record_index == damage_counter_change_records_before + 1U, "DamageRecord should point to the defense counter-change receipt");
    require(first_damage->damage_counter_change_record_count == 1U, "DamageRecord should carry exactly one defense counter-change row");
    const auto& defense_removed = game.counter_change_records.at(first_damage->first_damage_counter_change_record_index - 1U);
    require(defense_removed.counter_kind == mtgsim::CounterKind::Defense && defense_removed.amount == 3U && defense_removed.damage_result, "linked damage-result counter receipt should be defense removal");

    auto corrupted_damage_range = game;
    corrupted_damage_range.damage_records.back().damage_counter_change_record_count = 0U;
    const auto missing_range_violations = mtgsim::validate_game_state(corrupted_damage_range);
    require(has_violation_code(missing_range_violations, "damage_record.missing_counter_change_range"), "validator should reject damage receipts that remove defense without a counter-change range");

    mtgsim::deal_damage_to_target(game, source, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = battle}, 1);
    mtgsim::apply_state_based_actions(game);
    mtgsim::assert_valid_game_state(game);
    require(mtgsim::object(game, battle).zone == mtgsim::Zone::Graveyard, "zero-defense battle should move to owner graveyard as SBA");
    require(mtgsim::object_counter_count(game, battle, mtgsim::CounterKind::Defense) == 0U, "defense counters should clear on zone change");
}

