void test_battle_protector_blocks_attackers_to_battle() {
    auto game = make_battle_game();
    start_empty_unshuffled(game);
    const auto battle = mtgsim::ObjectId{1};
    const auto attacker = mtgsim::ObjectId{2};
    const auto alpha_guard = mtgsim::ObjectId{6};
    const auto beta_guard = mtgsim::ObjectId{8};
    mtgsim::move_object(game, battle, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, attacker, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, alpha_guard, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, beta_guard, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    make_ready(game, attacker);
    make_ready(game, alpha_guard);
    make_ready(game, beta_guard);
    game.step = mtgsim::Step::DeclareAttackers;
    game.active_player = mtgsim::PlayerId{1};
    require(mtgsim::declare_attacker_to_target(game, mtgsim::PlayerId{1}, attacker, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = battle}), "battle attack declaration should succeed");
    game.step = mtgsim::Step::DeclareBlockers;
    require(!mtgsim::can_declare_blocker(game, mtgsim::PlayerId{1}, alpha_guard, attacker), "battle controller should not block an attacker aimed at a battle protected by opponent");
    require(mtgsim::can_declare_blocker(game, mtgsim::PlayerId{2}, beta_guard, attacker), "battle protector should be able to block attackers to that battle");
    require(mtgsim::declare_blocker(game, mtgsim::PlayerId{2}, beta_guard, attacker), "protector block should succeed");
    mtgsim::assert_valid_game_state(game);
}

