void test_modal_action_enumeration_emits_mode_variants() {
    auto game = make_modal_game();
    const auto charm = mtgsim::ObjectId{1};
    const auto bear = mtgsim::ObjectId{5};
    mtgsim::move_object(game, charm, mtgsim::PlayerId{1}, mtgsim::Zone::Hand);
    mtgsim::move_object(game, bear, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    game.priority_player = mtgsim::PlayerId{1};

    const auto actions = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{1});
    auto count_mode = [&](mtgsim::u32 mode_index) {
        return static_cast<int>(std::count_if(actions.begin(), actions.end(), [&](const mtgsim::LegalAction& action) {
            return action.kind == mtgsim::ActionKind::CastSpellFromHandPaid && action.object == charm && action.mode_index == mode_index;
        }));
    };
    require(count_mode(0) == 0, "modal card should not emit an unmodeed cast action");
    require(count_mode(1) == 3, "any-target mode should emit player/player/object target variants");
    require(count_mode(2) == 1, "untargeted gain-life mode should emit one action");
    require(count_mode(3) == 1, "untargeted draw mode should emit one action");
}

void test_modal_targeted_mode_becomes_illegal_before_resolution() {
    auto game = make_modal_game();
    const auto charm = mtgsim::ObjectId{1};
    const auto bear = mtgsim::ObjectId{5};
    mtgsim::move_object(game, charm, mtgsim::PlayerId{1}, mtgsim::Zone::Hand);
    mtgsim::move_object(game, bear, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);

    require(mtgsim::cast_from_hand_to_stack_paying_mana_with_mode(game, mtgsim::PlayerId{1}, charm, 1, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = bear}), "targeted modal mode should cast");
    mtgsim::move_object(game, bear, mtgsim::PlayerId{2}, mtgsim::Zone::Exile);
    mtgsim::resolve_top_of_stack(game);
    require(mtgsim::object(game, bear).zone == mtgsim::Zone::Exile, "illegal target should stay exiled");
    require(mtgsim::object(game, bear).damage_marked == 0U, "illegal target should not be damaged on resolution");
}

void test_modal_counter_and_token_modes_use_selected_payload() {
    auto game = make_modal_game();
    set_main_phase_priority(game);
    const auto growth = mtgsim::ObjectId{2};
    const auto bear = mtgsim::ObjectId{5};
    mtgsim::move_object(game, growth, mtgsim::PlayerId{1}, mtgsim::Zone::Hand);
    mtgsim::move_object(game, bear, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);

    require(mtgsim::cast_from_hand_to_stack_paying_mana_with_mode(game, mtgsim::PlayerId{1}, growth, 1, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = bear}), "counter mode should cast with creature target");
    mtgsim::resolve_top_of_stack(game);
    require(mtgsim::object_counter_count(game, bear, mtgsim::CounterKind::PlusOnePlusOne) == 1U, "counter mode should add selected counter payload");

    mtgsim::move_object(game, growth, mtgsim::PlayerId{1}, mtgsim::Zone::Hand);
    require(mtgsim::cast_from_hand_to_stack_paying_mana_with_mode(game, mtgsim::PlayerId{1}, growth, 2), "token mode should cast without target");
    mtgsim::resolve_top_of_stack(game);
    const auto& battlefield = mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    require(std::any_of(battlefield.begin(), battlefield.end(), [&](mtgsim::ObjectId id) { return mtgsim::object(game, id).token; }), "token mode should create a token permanent");
}

void test_validation_catches_modal_stack_metadata_errors() {
    auto game = make_modal_game();
    const auto charm = mtgsim::ObjectId{1};
    mtgsim::move_object(game, charm, mtgsim::PlayerId{1}, mtgsim::Zone::Stack);
    auto violations = mtgsim::validate_game_state(game);
    require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& violation) {
        return violation.code == "modal.missing_choice";
    }), "validation should catch modal stack object without chosen mode");

    mtgsim::object(game, charm).chosen_mode_index = 99U;
    violations = mtgsim::validate_game_state(game);
    require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& violation) {
        return violation.code == "modal.invalid_choice";
    }), "validation should catch out-of-range mode choice");

    mtgsim::move_object(game, charm, mtgsim::PlayerId{1}, mtgsim::Zone::Graveyard);
    mtgsim::object(game, charm).chosen_mode_index = 1U;
    violations = mtgsim::validate_game_state(game);
    require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& violation) {
        return violation.code == "object.chosen_mode_outside_stack";
    }), "validation should catch stale mode choice outside stack");
}


mtgsim::GameState make_static_effect_game(std::uint64_t seed = 25025) {
    mtgsim::StaticEffectDefinition anthem_effect;
    anthem_effect.name = "Team anthem";
    anthem_effect.scope = mtgsim::StaticEffectScope::CreaturesYouControl;
    anthem_effect.affected_type_mask = mtgsim::TypeCreature;
    anthem_effect.power_modifier = 1;
    anthem_effect.toughness_modifier = 1;

    mtgsim::CardDefinition anthem;
    anthem.name = "Static Anthem";
    anthem.type_mask = mtgsim::TypeEnchantment;
    anthem.static_effects.push_back(anthem_effect);

    mtgsim::CardDefinition alpha_bear;
    alpha_bear.name = "Static Alpha Bear";
    alpha_bear.type_mask = mtgsim::TypeCreature;
    alpha_bear.printed_power = 2;
    alpha_bear.printed_toughness = 2;

    mtgsim::StaticEffectDefinition wings_effect;
    wings_effect.name = "Levitation seam";
    wings_effect.scope = mtgsim::StaticEffectScope::CreaturesYouControl;
    wings_effect.affected_type_mask = mtgsim::TypeCreature;
    wings_effect.granted_ability_mask = mtgsim::AbilityFlying;

    mtgsim::CardDefinition wings;
    wings.name = "Static Wings";
    wings.type_mask = mtgsim::TypeEnchantment;
    wings.static_effects.push_back(wings_effect);

    mtgsim::StaticEffectDefinition haste_effect;
    haste_effect.name = "Battle fervor";
    haste_effect.scope = mtgsim::StaticEffectScope::CreaturesYouControl;
    haste_effect.affected_type_mask = mtgsim::TypeCreature;
    haste_effect.granted_ability_mask = mtgsim::AbilityHaste;

    mtgsim::CardDefinition fervor;
    fervor.name = "Static Fervor";
    fervor.type_mask = mtgsim::TypeEnchantment;
    fervor.static_effects.push_back(haste_effect);

    mtgsim::CardDefinition beta_bear;
    beta_bear.name = "Static Beta Bear";
    beta_bear.type_mask = mtgsim::TypeCreature;
    beta_bear.printed_power = 2;
    beta_bear.printed_toughness = 2;

    mtgsim::StaticEffectDefinition plague_effect;
    plague_effect.name = "Tiny plague";
    plague_effect.scope = mtgsim::StaticEffectScope::AllCreatures;
    plague_effect.affected_type_mask = mtgsim::TypeCreature;
    plague_effect.power_modifier = -1;
    plague_effect.toughness_modifier = -1;

    mtgsim::CardDefinition plague;
    plague.name = "Static Plague";
    plague.type_mask = mtgsim::TypeEnchantment;
    plague.static_effects.push_back(plague_effect);

    mtgsim::CardDefinition small;
    small.name = "Static Small Creature";
    small.type_mask = mtgsim::TypeCreature;
    small.printed_power = 1;
    small.printed_toughness = 1;

    std::vector<mtgsim::CardDefinition> defs = {anthem, alpha_bear, wings, fervor, beta_bear, plague, small};
    std::vector<mtgsim::PlayerDeck> decks = {
        {"Alpha", {0, 1, 2, 3, 6}},
        {"Beta", {4, 5}}
    };
    return mtgsim::make_game(std::move(defs), decks, seed);
}

void make_object_ready(mtgsim::GameState& game, mtgsim::ObjectId id) {
    auto& obj = mtgsim::object(game, id);
    auto& controller = mtgsim::player(game, obj.controller);
    if (controller.turn_start_index == 0U) {
        controller.turn_start_index = 1U;
    }
    obj.controlled_since_turn_start_index = controller.turn_start_index - 1U;
}

void test_static_anthem_updates_derived_power_toughness() {
    auto game = make_static_effect_game();
    const auto anthem = mtgsim::ObjectId{1};
    const auto alpha_bear = mtgsim::ObjectId{2};
    const auto beta_bear = mtgsim::ObjectId{6};
    mtgsim::move_object(game, anthem, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, alpha_bear, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, beta_bear, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);

    require(mtgsim::static_power_modifier(game, alpha_bear) == 1, "anthem should statically modify controlled creature power");
    require(mtgsim::static_toughness_modifier(game, alpha_bear) == 1, "anthem should statically modify controlled creature toughness");
    require(mtgsim::effective_power(game, alpha_bear) == 3 && mtgsim::effective_toughness(game, alpha_bear) == 3, "controlled bear should be 3/3");
    require(mtgsim::effective_power(game, beta_bear) == 2 && mtgsim::effective_toughness(game, beta_bear) == 2, "opposing bear should not receive your anthem");

    mtgsim::move_object(game, anthem, mtgsim::PlayerId{1}, mtgsim::Zone::Graveyard);
    require(mtgsim::effective_power(game, alpha_bear) == 2 && mtgsim::effective_toughness(game, alpha_bear) == 2, "static P/T effect should disappear when source leaves battlefield");
}

void test_static_ability_grant_affects_evasion_and_removal() {
    auto game = make_static_effect_game();
    const auto attacker = mtgsim::ObjectId{2};
    const auto wings = mtgsim::ObjectId{3};
    const auto blocker = mtgsim::ObjectId{6};
    mtgsim::move_object(game, attacker, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, wings, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, blocker, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);
    make_object_ready(game, attacker);
    make_object_ready(game, blocker);
    game.active_player = mtgsim::PlayerId{1};
    game.priority_player = mtgsim::PlayerId{1};
    game.step = mtgsim::Step::DeclareAttackers;

    require(mtgsim::object_has_ability(game, attacker, mtgsim::AbilityFlying), "static effect should grant flying");
    require(mtgsim::declare_attacker(game, mtgsim::PlayerId{1}, attacker, mtgsim::PlayerId{2}), "flying attacker should be declarable");
    game.step = mtgsim::Step::DeclareBlockers;
    require(!mtgsim::can_declare_blocker(game, mtgsim::PlayerId{2}, blocker, attacker), "ground creature should not block statically-granted flying");

    mtgsim::move_object(game, wings, mtgsim::PlayerId{1}, mtgsim::Zone::Graveyard);
    require(!mtgsim::object_has_ability(game, attacker, mtgsim::AbilityFlying), "static-granted flying should disappear with source");
    require(mtgsim::can_declare_blocker(game, mtgsim::PlayerId{2}, blocker, attacker), "ground blocker should become legal after flying effect disappears");
}

void test_static_haste_grant_feeds_action_enumeration() {
    auto game = make_static_effect_game();
    const auto attacker = mtgsim::ObjectId{2};
    const auto fervor = mtgsim::ObjectId{4};
    mtgsim::move_object(game, attacker, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, fervor, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    game.active_player = mtgsim::PlayerId{1};
    game.priority_player = mtgsim::PlayerId{1};
    game.step = mtgsim::Step::DeclareAttackers;

    require(mtgsim::object_has_summoning_sickness(game, attacker) == false, "static haste grant should bypass summoning sickness helper");
    const auto actions = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{1});
    const auto attack_actions = std::count_if(actions.begin(), actions.end(), [&](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::DeclareAttacker && action.object == attacker;
    });
    require(attack_actions >= 1, "statically-granted haste should surface attack actions");
}

void test_static_negative_toughness_effect_feeds_sba() {
    auto game = make_static_effect_game();
    const auto small = mtgsim::ObjectId{5};
    const auto plague = mtgsim::ObjectId{7};
    mtgsim::move_object(game, small, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, plague, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);

    require(mtgsim::effective_toughness(game, small) == 0, "static -1/-1 effect should reduce 1/1 to zero toughness");
    mtgsim::apply_state_based_actions(game);
    require(mtgsim::object(game, small).zone == mtgsim::Zone::Graveyard, "zero-toughness static effect should feed SBA movement");
}

void test_validation_catches_inactive_static_effect_definition() {
    auto game = make_static_effect_game();
    mtgsim::StaticEffectDefinition bad;
    bad.name = "No-op";
    bad.scope = mtgsim::StaticEffectScope::CreaturesYouControl;
    bad.affected_type_mask = mtgsim::TypeCreature;
    game.definitions[0].static_effects.push_back(bad);
    const auto violations = mtgsim::validate_game_state(game);
    require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& violation) {
        return violation.code == "static_effect.inactive";
    }), "validation should flag inactive static-effect definitions");
}

mtgsim::GameState make_type_color_static_game(std::uint64_t seed = 27027) {
    mtgsim::StaticEffectDefinition animate_effect;
    animate_effect.name = "Land animation seam";
    animate_effect.scope = mtgsim::StaticEffectScope::PermanentsYouControl;
    animate_effect.affected_type_mask = mtgsim::TypeLand;
    animate_effect.added_type_mask = mtgsim::TypeCreature;
    animate_effect.power_modifier = 2;
    animate_effect.toughness_modifier = 2;
    animate_effect.granted_ability_mask = mtgsim::AbilityHaste;

    mtgsim::CardDefinition animator;
    animator.name = "Type Animator";
    animator.type_mask = mtgsim::TypeEnchantment;
    animator.static_effects.push_back(animate_effect);

    mtgsim::StaticEffectDefinition painter_effect;
    painter_effect.name = "Blue painter seam";
    painter_effect.scope = mtgsim::StaticEffectScope::AllPermanents;
    painter_effect.affected_type_mask = mtgsim::TypeCreature;
    painter_effect.sets_color = true;
    painter_effect.set_color_mask = mtgsim::ColorBlue;

    mtgsim::CardDefinition painter;
    painter.name = "Color Painter";
    painter.type_mask = mtgsim::TypeEnchantment;
    painter.static_effects.push_back(painter_effect);

    mtgsim::StaticEffectDefinition type_removal_effect;
    type_removal_effect.name = "Creature eraser seam";
    type_removal_effect.scope = mtgsim::StaticEffectScope::AllCreatures;
    type_removal_effect.affected_type_mask = mtgsim::TypeCreature;
    type_removal_effect.removed_type_mask = mtgsim::TypeCreature;

    mtgsim::CardDefinition type_eraser;
    type_eraser.name = "Type Eraser";
    type_eraser.type_mask = mtgsim::TypeEnchantment;
    type_eraser.static_effects.push_back(type_removal_effect);

    mtgsim::CardDefinition forest;
    forest.name = "Layer Forest";
    forest.type_mask = mtgsim::TypeLand;
    forest.color_mask = mtgsim::ColorGreen;

    mtgsim::CardDefinition goblin;
    goblin.name = "Layer Goblin";
    goblin.type_mask = mtgsim::TypeCreature;
    goblin.printed_power = 2;
    goblin.printed_toughness = 2;
    goblin.color_mask = mtgsim::ColorRed;

    mtgsim::CardDefinition guardian;
    guardian.name = "Blue Ward Guardian";
    guardian.type_mask = mtgsim::TypeCreature;
    guardian.printed_power = 2;
    guardian.printed_toughness = 2;
    guardian.color_mask = mtgsim::ColorWhite;
    guardian.protection_color_mask = mtgsim::ColorBlue;

    std::vector<mtgsim::CardDefinition> defs = {animator, painter, type_eraser, forest, goblin, guardian};
    std::vector<mtgsim::PlayerDeck> decks = {
        {"Alpha", {0, 1, 2, 3, 4, 5}},
        {"Beta", {4, 5}}
    };
    return mtgsim::make_game(std::move(defs), decks, seed);
}

void test_static_type_effect_animates_land_for_actions_and_sba() {
    auto game = make_type_color_static_game();
    const auto animator = mtgsim::ObjectId{1};
    const auto forest = mtgsim::ObjectId{4};
    mtgsim::move_object(game, animator, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, forest, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    game.active_player = mtgsim::PlayerId{1};
    game.priority_player = mtgsim::PlayerId{1};
    game.step = mtgsim::Step::DeclareAttackers;

    require(mtgsim::object_has_type(game, forest, mtgsim::TypeLand), "animated land should remain a land");
    require(mtgsim::object_has_type(game, forest, mtgsim::TypeCreature), "static layer-4 seam should add creature type");
    require(mtgsim::effective_power(game, forest) == 2 && mtgsim::effective_toughness(game, forest) == 2, "animated land should receive static P/T modifier through derived helpers");
    require(mtgsim::object_has_ability(game, forest, mtgsim::AbilityHaste), "type-filtered static effect should grant haste to the animated land");
    require(!mtgsim::object_has_summoning_sickness(game, forest), "static haste should make the animated land attackable this turn");
    require(mtgsim::can_declare_attacker(game, mtgsim::PlayerId{1}, forest, mtgsim::PlayerId{2}), "animated land should be a legal attacker");

    mtgsim::move_object(game, animator, mtgsim::PlayerId{1}, mtgsim::Zone::Graveyard);
    require(!mtgsim::object_has_type(game, forest, mtgsim::TypeCreature), "animated land should stop being a creature when source leaves");
}

void test_static_type_removal_stops_creature_combat_and_creature_sba() {
    auto game = make_type_color_static_game();
    const auto type_eraser = mtgsim::ObjectId{3};
    const auto goblin = mtgsim::ObjectId{5};
    mtgsim::move_object(game, type_eraser, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, goblin, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    game.active_player = mtgsim::PlayerId{1};
    game.priority_player = mtgsim::PlayerId{1};
    game.step = mtgsim::Step::DeclareAttackers;

    require(!mtgsim::object_has_type(game, goblin, mtgsim::TypeCreature), "static layer-4 seam should remove creature type");
    require(!mtgsim::can_declare_attacker(game, mtgsim::PlayerId{1}, goblin, mtgsim::PlayerId{2}), "noncreature after type removal cannot attack");
    mtgsim::mark_damage(game, goblin, 99);
    mtgsim::apply_state_based_actions(game);
    require(mtgsim::object(game, goblin).zone == mtgsim::Zone::Battlefield, "creature lethal-damage SBA should not apply after type removal");

    mtgsim::move_object(game, type_eraser, mtgsim::PlayerId{1}, mtgsim::Zone::Graveyard);
    require(mtgsim::object_has_type(game, goblin, mtgsim::TypeCreature), "creature type should return when type-removal source leaves");
    mtgsim::apply_state_based_actions(game);
    require(mtgsim::object(game, goblin).zone == mtgsim::Zone::Graveyard, "returned creature type should make marked lethal damage matter again");
}

void test_static_color_effect_recolors_source_characteristics() {
    auto game = make_type_color_static_game();
    const auto painter = mtgsim::ObjectId{2};
    const auto goblin = mtgsim::ObjectId{5};
    const auto guardian = mtgsim::ObjectId{6};
    mtgsim::move_object(game, painter, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, goblin, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, guardian, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);

    require(mtgsim::object_color_mask(game, goblin) == mtgsim::ColorBlue, "static layer-5 seam should recolor the creature blue");
    require(mtgsim::target_has_protection_from_source(game, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = guardian}, goblin), "protection check should consume statically recolored source characteristics");

    mtgsim::move_object(game, painter, mtgsim::PlayerId{1}, mtgsim::Zone::Graveyard);
    require(mtgsim::object_color_mask(game, goblin) == mtgsim::ColorRed, "printed/source color should return when color effect leaves");
    require(!mtgsim::target_has_protection_from_source(game, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = guardian}, goblin), "protection check should observe disappeared color effect");
}

void test_validation_catches_invalid_static_type_and_color_masks() {
    auto game = make_type_color_static_game();
    mtgsim::StaticEffectDefinition bad_type;
    bad_type.name = "Bad type bits";
    bad_type.scope = mtgsim::StaticEffectScope::AllPermanents;
    bad_type.affected_type_mask = mtgsim::TypeLand;
    bad_type.added_type_mask = 1u << 25;
    game.definitions[0].static_effects.push_back(bad_type);

    mtgsim::StaticEffectDefinition bad_color;
    bad_color.name = "Bad color bits";
    bad_color.scope = mtgsim::StaticEffectScope::AllPermanents;
    bad_color.affected_type_mask = mtgsim::TypeCreature;
    bad_color.added_color_mask = 1u << 20;
    game.definitions[1].static_effects.push_back(bad_color);

    const auto violations = mtgsim::validate_game_state(game);
    require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& violation) {
        return violation.code == "static_effect.invalid_type_mask";
    }), "validation should catch invalid type-layer bits");
    require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& violation) {
        return violation.code == "static_effect.invalid_color_mask";
    }), "validation should catch invalid color-layer bits");
}


