    set_base.scope = mtgsim::StaticEffectScope::AllCreatures;
    set_base.affected_type_mask = mtgsim::TypeCreature;
    set_base.sets_power_toughness = true;
    set_base.set_power = 4;
    set_base.set_toughness = 4;

    mtgsim::CardDefinition base_setter;
