    mtgsim::StaticEffectDefinition anthem_effect;
    anthem_effect.name = "Post-base anthem";
    anthem_effect.scope = mtgsim::StaticEffectScope::AllCreatures;
    anthem_effect.affected_type_mask = mtgsim::TypeCreature;
    anthem_effect.power_modifier = 1;
    anthem_effect.toughness_modifier = 1;

    mtgsim::CardDefinition anthem;
    anthem.name = "Layer Anthem";
    anthem.type_mask = mtgsim::TypeEnchantment;
    anthem.static_effects.push_back(anthem_effect);

    mtgsim::StaticEffectDefinition zero_base;
    zero_base.name = "Base zero seam";
    zero_base.scope = mtgsim::StaticEffectScope::AllCreatures;
    zero_base.affected_type_mask = mtgsim::TypeCreature;
    zero_base.sets_power_toughness = true;
    zero_base.set_power = 0;
