    blocker.printed_power = 2;
    blocker.printed_toughness = 2;

    mtgsim::StaticEffectDefinition pump;
    pump.name = "Giant growth seam";
    pump.scope = mtgsim::StaticEffectScope::Source;
    pump.affected_type_mask = mtgsim::TypeCreature;
    pump.power_modifier = 3;
    pump.toughness_modifier = 3;
    mtgsim::CardDefinition growth;
