    wings.effect_kind = mtgsim::EffectKind::CreateContinuousEffect;
    wings.effect_amount = 1;
    wings.target_mask = mtgsim::TargetObject;
    wings.continuous_effect = grant_flying;
    wings.continuous_effect_duration = mtgsim::ContinuousEffectDuration::UntilCleanup;

    mtgsim::StaticEffectDefinition remove_flying;
    remove_flying.name = "Temporary grounding seam";
    remove_flying.scope = mtgsim::StaticEffectScope::Source;
    remove_flying.affected_type_mask = mtgsim::TypeCreature;
    remove_flying.removed_ability_mask = mtgsim::AbilityFlying;
    mtgsim::CardDefinition grounding;
