    grounding.target_mask = mtgsim::TargetObject;
    grounding.continuous_effect = remove_flying;
    grounding.continuous_effect_duration = mtgsim::ContinuousEffectDuration::UntilCleanup;

    mtgsim::CardDefinition land;
    land.name = "Temporary Field";
