    mtgsim::StaticEffectDefinition animate;
    animate.name = "Temporary animation seam";
    animate.scope = mtgsim::StaticEffectScope::Source;
    animate.affected_type_mask = mtgsim::TypeLand;
    animate.added_type_mask = mtgsim::TypeCreature;
    animate.sets_power_toughness = true;
