    animate.set_toughness = 3;
    mtgsim::CardDefinition animate_spell;
    animate_spell.name = "Temporary Animation";
    animate_spell.type_mask = mtgsim::TypeInstant;
    animate_spell.effect_kind = mtgsim::EffectKind::CreateContinuousEffect;
    animate_spell.effect_amount = 1;
    animate_spell.target_mask = mtgsim::TargetObject;
    animate_spell.continuous_effect = animate;
    animate_spell.continuous_effect_duration = mtgsim::ContinuousEffectDuration::UntilCleanup;

    mtgsim::StaticEffectDefinition blessing_effect;
    blessing_effect.name = "Static flight field";
    blessing_effect.scope = mtgsim::StaticEffectScope::AllCreatures;
    blessing_effect.affected_type_mask = mtgsim::TypeCreature;
    blessing_effect.granted_ability_mask = mtgsim::AbilityFlying;
