void test_gain_control_spell_moves_battlefield_container_and_owner_graveyard() {
    auto game = make_control_change_game();
    const auto stolen = mtgsim::ObjectId{1};
    const auto control_spell = mtgsim::ObjectId{4};
    mtgsim::move_object(game, stolen, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, control_spell, mtgsim::PlayerId{2}, mtgsim::Zone::Hand);
    set_main_phase_priority(game, mtgsim::PlayerId{2});

    require(mtgsim::cast_from_hand_to_stack_paying_mana_with_target(game, mtgsim::PlayerId{2}, control_spell, mtgsim::TargetRef{.kind = mtgsim::TargetKind::Object, .object = stolen}), "control spell should cast with a permanent target");
    mtgsim::resolve_top_of_stack(game);

    require(mtgsim::object(game, stolen).controller == mtgsim::PlayerId{2}, "control effect should update object controller");
    require(mtgsim::object(game, stolen).owner == mtgsim::PlayerId{1}, "control effect must not change owner");
    require(mtgsim::object(game, stolen).zone == mtgsim::Zone::Battlefield, "control effect should not change zone");
    require(std::find(mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield).begin(), mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield).end(), stolen) == mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield).end(), "old controller battlefield should no longer contain stolen object");
    require(std::find(mtgsim::zone(game, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield).begin(), mtgsim::zone(game, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield).end(), stolen) != mtgsim::zone(game, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield).end(), "new controller battlefield should contain stolen object");
    mtgsim::assert_valid_game_state(game);

    mtgsim::mark_damage(game, stolen, 3);
    mtgsim::apply_state_based_actions(game);
    require(mtgsim::object(game, stolen).zone == mtgsim::Zone::Graveyard, "stolen lethal creature should die");
    require(mtgsim::object(game, stolen).controller == mtgsim::PlayerId{1}, "graveyard object controller should reset to owner in non-battlefield zone");
    require(std::find(mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Graveyard).begin(), mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Graveyard).end(), stolen) != mtgsim::zone(game, mtgsim::PlayerId{1}, mtgsim::Zone::Graveyard).end(), "stolen creature should move to owner graveyard");
}

void test_gain_control_helper_updates_sickness_and_clears_combat() {
    auto game = make_control_change_game();
    const auto attacker = mtgsim::ObjectId{1};
    mtgsim::move_object(game, attacker, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    make_object_ready(game, attacker);
    game.active_player = mtgsim::PlayerId{1};
    game.priority_player = mtgsim::PlayerId{1};
    game.step = mtgsim::Step::DeclareAttackers;
    require(mtgsim::declare_attacker(game, mtgsim::PlayerId{1}, attacker, mtgsim::PlayerId{2}), "ready creature should attack before control changes");

    require(mtgsim::gain_control_of_permanent(game, mtgsim::PlayerId{2}, attacker), "control helper should transfer battlefield permanent");
    require(!mtgsim::object(game, attacker).attacking, "control change should remove creature from combat");
    require(!mtgsim::object(game, attacker).blocked, "control change should clear blocked memory");
    require(mtgsim::object(game, attacker).defending_player == mtgsim::PlayerId{}, "control change should clear defending player metadata");
    require(mtgsim::object_has_summoning_sickness(game, attacker), "new controller should not have controlled the creature since the beginning of their current turn");
    mtgsim::assert_valid_game_state(game);
}

void test_control_change_recomputes_static_effect_scopes() {
    auto game = make_control_change_game();
    const auto bear = mtgsim::ObjectId{1};
    const auto anthem = mtgsim::ObjectId{5};
    mtgsim::move_object(game, bear, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, anthem, mtgsim::PlayerId{2}, mtgsim::Zone::Battlefield);

    require(mtgsim::effective_power(game, bear) == 2, "opponent-controlled anthem should not boost this creature before control changes");
    require(mtgsim::gain_control_of_permanent(game, mtgsim::PlayerId{2}, bear), "control helper should transfer to anthem controller");
    require(mtgsim::effective_power(game, bear) == 3, "new controller's static creatures-you-control effect should start applying");
    require(mtgsim::effective_toughness(game, bear) == 3, "static toughness modifier should also follow controller change");
}

void test_control_change_action_enumeration_casts_targeted_control_spell() {
    auto game = make_control_change_game();
    const auto bear = mtgsim::ObjectId{1};
    const auto control_spell = mtgsim::ObjectId{4};
    mtgsim::move_object(game, bear, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, control_spell, mtgsim::PlayerId{2}, mtgsim::Zone::Hand);
    set_main_phase_priority(game, mtgsim::PlayerId{2});

    const auto actions = mtgsim::enumerate_legal_actions(game, mtgsim::PlayerId{2});
    const auto it = std::find_if(actions.begin(), actions.end(), [&](const mtgsim::LegalAction& action) {
        return action.kind == mtgsim::ActionKind::CastSpellFromHandPaid && action.object == control_spell && action.target.kind == mtgsim::TargetKind::Object && action.target.object == bear;
    });
    require(it != actions.end(), "legal action mask should include targeted control spell");
    require(mtgsim::apply_action(game, *it), "targeted control spell action should apply");
    mtgsim::resolve_top_of_stack(game);
    require(mtgsim::object(game, bear).controller == mtgsim::PlayerId{2}, "resolved action path should transfer control");
}

