void test_copy_effect_clears_on_zone_change_and_validation_catches_bad_copy_metadata() {
    auto game = make_copy_effect_game();
    const auto mirror = mtgsim::ObjectId{1};
    const auto dragon = mtgsim::ObjectId{2};
    mtgsim::move_object(game, mirror, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, dragon, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    require(mtgsim::become_copy_of_permanent(game, mirror, dragon), "copy should start");
    mtgsim::move_object(game, mirror, mtgsim::PlayerId{1}, mtgsim::Zone::Graveyard);
    require(!mtgsim::object_has_copy_effect(game, mirror), "copy effect should clear as the object leaves the battlefield");
    require(mtgsim::object_copiable_definition_index(game, mirror) == 0U, "object should report printed definition again after zone change");
    mtgsim::assert_valid_game_state(game);

    mtgsim::object(game, mirror).has_copy_effect = true;
    mtgsim::object(game, mirror).copied_definition_index = 999U;
    const auto violations = mtgsim::validate_game_state(game);
    require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& violation) {
        return violation.code == "copy.outside_battlefield";
    }), "validation should catch copy effect outside battlefield");
    require(std::any_of(violations.begin(), violations.end(), [](const mtgsim::InvariantViolation& violation) {
        return violation.code == "copy.invalid_definition";
    }), "validation should catch invalid copied definition index");
}

void test_state_based_action_record_links_damage_destroy_and_regeneration() {
    mtgsim::CardDefinition bear;
    bear.name = "SBA Record Bear";
    bear.type_mask = mtgsim::TypeCreature;
    bear.printed_power = 2;
    bear.printed_toughness = 2;

    mtgsim::CardDefinition shielded_bear = bear;
    shielded_bear.name = "SBA Record Shielded Bear";

    std::vector<mtgsim::CardDefinition> defs = {bear, shielded_bear};
    std::vector<mtgsim::PlayerDeck> decks = {
        {"Alpha", {0, 1}},
        {"Beta", {}}
    };
    auto game = mtgsim::make_game(std::move(defs), decks, 7040052);
    start_empty_unshuffled(game);

    const auto doomed = mtgsim::ObjectId{1};
    const auto shielded = mtgsim::ObjectId{2};
    mtgsim::move_object(game, doomed, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);
    mtgsim::move_object(game, shielded, mtgsim::PlayerId{1}, mtgsim::Zone::Battlefield);

    const auto before_zone_records = mtgsim::zone_change_record_count(game);
    const auto before_sba_records = mtgsim::state_based_action_record_count(game);
    mtgsim::mark_damage(game, doomed, 2);
    mtgsim::apply_state_based_actions(game);

    require(mtgsim::state_based_action_record_count(game) == before_sba_records + 1U, "lethal damage SBA should append a structured StateBasedActionRecord");
    const auto* destroy_record = mtgsim::latest_state_based_action_record(game);
    require(destroy_record != nullptr, "latest StateBasedActionRecord should be available");
    require(destroy_record->kind == mtgsim::StateBasedActionKind::CreatureDamageDestroy, "record should identify the lethal-damage SBA kind");
    require(destroy_record->object == doomed, "record should identify the damaged creature");
    require(destroy_record->object_zone == mtgsim::Zone::Battlefield, "record should snapshot the pre-SBA object zone");
    require(destroy_record->object_zone_change_index != 0U, "record should snapshot object zone identity");
    require(destroy_record->damage_marked == 2U, "record should snapshot marked lethal damage");
    require(destroy_record->effective_toughness == 2, "record should snapshot effective toughness used by SBA");
    require(!destroy_record->regeneration_applied, "unshielded lethal damage should not mark regeneration");
    require(destroy_record->zone_change_record_index != 0U, "unshielded lethal damage should link the resulting ZoneChangeRecord");
    require(destroy_record->object_left_battlefield, "linked movement should be recognized as battlefield exit");
    require(mtgsim::zone_change_record_count(game) == before_zone_records + 1U, "unshielded lethal SBA should append one zone-change record");
    const auto& linked_zone = game.zone_change_records[destroy_record->zone_change_record_index - 1U];
    require(linked_zone.object == doomed, "linked ZoneChangeRecord should belong to the same object");
    require(linked_zone.from_zone == mtgsim::Zone::Battlefield, "linked ZoneChangeRecord should leave the battlefield");
    require(linked_zone.requested_zone == mtgsim::Zone::Graveyard, "linked ZoneChangeRecord should preserve the graveyard SBA request");
    require(linked_zone.sequence > destroy_record->sequence, "linked movement should occur after the SBA record event");
    require(std::any_of(game.event_records.begin(), game.event_records.end(), [&](const mtgsim::EventRecord& event_record) {
        return event_record.kind == mtgsim::EventRecordKind::StateBasedAction &&
               event_record.state_based_action_record_index == mtgsim::state_based_action_record_count(game) &&
               event_record.object == doomed;
    }), "typed EventRecord spine should link the StateBasedActionRecord");
    mtgsim::assert_valid_game_state(game);

    auto corrupted = game;
    corrupted.state_based_action_records.back().zone_change_record_index = 0U;
    const auto no_result_violations = mtgsim::validate_game_state(corrupted);
    require(std::any_of(no_result_violations.begin(), no_result_violations.end(), [](const mtgsim::InvariantViolation& violation) {
        return violation.code == "state_based_action_record.damage_destroy_no_result";
    }), "validator should reject a lethal damage SBA record with neither zone movement nor regeneration");

    mtgsim::add_regeneration_shield(game, shielded);
    const auto before_regen_zone_records = mtgsim::zone_change_record_count(game);
    mtgsim::mark_damage(game, shielded, 2);
    mtgsim::apply_state_based_actions(game);

    const auto* regeneration_record = mtgsim::latest_state_based_action_record(game);
    require(regeneration_record != nullptr, "regeneration SBA should leave a structured record");
    require(regeneration_record->kind == mtgsim::StateBasedActionKind::CreatureDamageDestroy, "regeneration should still be recorded as a damage-destroy SBA");
    require(regeneration_record->object == shielded, "regeneration record should identify the shielded creature");
    require(regeneration_record->regeneration_applied, "regeneration should be captured on the SBA record");
    require(regeneration_record->regeneration_shields_before == 1U && regeneration_record->regeneration_shields_after == 0U, "record should capture the consumed regeneration shield");
    require(regeneration_record->zone_change_record_index == 0U, "regenerated SBA should not link a zone movement");
    require(mtgsim::zone_change_record_count(game) == before_regen_zone_records, "regenerated damage SBA should not move the object between zones");
    require(mtgsim::object(game, shielded).zone == mtgsim::Zone::Battlefield, "regenerated creature should remain on the battlefield");
    require(mtgsim::object(game, shielded).damage_marked == 0U, "regeneration should clear marked damage");
    mtgsim::assert_valid_game_state(game);

    auto corrupted_regen = game;
    corrupted_regen.state_based_action_records.back().regeneration_shields_after = corrupted_regen.state_based_action_records.back().regeneration_shields_before;
    const auto regen_violations = mtgsim::validate_game_state(corrupted_regen);
    require(std::any_of(regen_violations.begin(), regen_violations.end(), [](const mtgsim::InvariantViolation& violation) {
        return violation.code == "state_based_action_record.regeneration_not_consumed";
    }), "validator should reject regeneration metadata that does not consume a shield");
}


